// ============================================================
// Create FFmpeg Video List v2.0
// Role:
// - 완료된 Scene Video 개수 검증
// - Scene 순서 정렬
// - 다운로드에 필요한 파일 메타데이터 정규화
// - fullpath 의존성 제거
// ============================================================

const config = $('Pipeline Config').first().json;

const items = $input.all();

const expectedScenes =
  Number(config.video.scenes);


// ============================================================
// 1. Config 검증
// ============================================================

if (
  !Number.isInteger(expectedScenes) ||
  expectedScenes <= 0
) {
  throw new Error(
    'Pipeline Config.video.scenes 값이 올바르지 않습니다.'
  );
}


// ============================================================
// 2. 입력 검증
// ============================================================

if (
  !Array.isArray(items) ||
  items.length === 0
) {
  throw new Error(
    '완료된 Scene Video 데이터가 없습니다.'
  );
}


if (
  items.length !== expectedScenes
) {
  throw new Error(
    `Video 개수 오류: ` +
    `예상 ${expectedScenes}개 / ` +
    `실제 ${items.length}개`
  );
}


// ============================================================
// 3. Scene 순서 정렬
// ============================================================

const sorted =
  [...items].sort(
    (a, b) =>
      Number(a.json.scene) -
      Number(b.json.scene)
  );


// ============================================================
// 4. Video Metadata 정규화
// ============================================================

const files =
  sorted.map(
    (item, index) => {

      const json =
        item.json || {};

      const expectedScene =
        index + 1;

      const scene =
        Number(json.scene);


      // ----------------------------------------
      // Scene 번호 검증
      // ----------------------------------------

      if (
        !Number.isInteger(scene)
      ) {
        throw new Error(
          `Video item ${expectedScene}: scene 번호가 없습니다.`
        );
      }


      if (
        scene !== expectedScene
      ) {
        throw new Error(
          `Scene 순서 오류: ` +
          `${expectedScene}번이 필요하지만 ` +
          `${scene}번이 들어왔습니다.`
        );
      }


      // ----------------------------------------
      // Filename 검증
      // ----------------------------------------

      const filename =
        typeof json.filename === 'string'
          ? json.filename.trim()
          : '';


      if (!filename) {
        throw new Error(
          `Scene ${scene}: filename이 없습니다.`
        );
      }


      if (
        !/\.(mp4|gif|webp)$/i.test(filename)
      ) {
        throw new Error(
          `Scene ${scene}: 지원하지 않는 Video 파일입니다: ${filename}`
        );
      }


      // ----------------------------------------
      // Normalized File Object
      // ----------------------------------------

      return {

        scene,

        filename,

        subfolder:
          json.subfolder || '',

        type:
          json.type || 'output',

        prompt_id:
          json.prompt_id || '',

        format:
          json.format || '',

        frame_rate:
          json.frame_rate || null

      };

    }
  );


// ============================================================
// 5. 최종 반환
// ============================================================

return [
  {
    json: {

      ready: true,

      video_count:
        files.length,

      expected_video_count:
        expectedScenes,

      files,

      run_name:
        config.run_name,

      pipeline_version:
        config.pipeline_version

    }
  }
];

// ============================================================
// Create Concat TXT v3.0
// Role:
// - Scene MP4 개수/순서 검증
// - Run별 저장 경로 기준 concat.txt 생성
// ============================================================

const config =
  $('Pipeline Config').first().json;

const items =
  $input.all();

const expectedScenes =
  Number(config.video.scenes);


if (
  !Number.isInteger(expectedScenes) ||
  expectedScenes <= 0
) {
  throw new Error(
    'Pipeline Config.video.scenes 값이 올바르지 않습니다.'
  );
}


if (
  !Array.isArray(items) ||
  items.length !== expectedScenes
) {
  throw new Error(
    `FFmpeg Video 개수 오류: ` +
    `예상 ${expectedScenes}개 / ` +
    `실제 ${items?.length || 0}개`
  );
}


const sorted =
  [...items].sort(
    (a, b) =>
      Number(a.json.scene) -
      Number(b.json.scene)
  );


const concatLines = [];


for (
  let index = 0;
  index < sorted.length;
  index++
) {

  const item =
    sorted[index];

  const json =
    item.json || {};

  const scene =
    Number(json.scene);

  const expectedScene =
    index + 1;


  if (
    !Number.isInteger(scene) ||
    scene !== expectedScene
  ) {
    throw new Error(
      `Scene 순서 오류: ` +
      `${expectedScene}번 필요 / 실제 ${scene}`
    );
  }


  const filename =
    typeof json.filename === 'string'
      ? json.filename.trim()
      : '';


  if (!filename) {
    throw new Error(
      `Scene ${scene}: filename이 없습니다.`
    );
  }


  if (
    !/\.mp4$/i.test(filename)
  ) {
    throw new Error(
      `Scene ${scene}: MP4 파일이 아닙니다: ${filename}`
    );
  }


  const filepath =
    `${config.paths.scene_video_folder}/${filename}`;


  concatLines.push(
    `file '${filepath.replace(/'/g, "'\\''")}'`
  );
}


const concatText =
  concatLines.join('\n');


if (!concatText.trim()) {
  throw new Error(
    'concat.txt 생성 결과가 비어 있습니다.'
  );
}


return [
  {
    json: {

      ready:
        true,

      video_count:
        sorted.length,

      concat_txt:
        concatText,

      concat_path:
        config.paths.concat_txt,

      output_video:
        config.paths.final_scene_video,

      run_id:
        config.run_id,

      run_name:
        config.run_name,

      pipeline_version:
        config.pipeline_version

    }
  }
];

const concatTxt = $json.concat_txt;

return [
  {
    json: {
      filename: 'concat.txt'
    },
    binary: {
      data: {
        data: Buffer.from(concatTxt, 'utf8').toString('base64'),
        mimeType: 'text/plain',
        fileName: 'concat.txt',
        fileExtension: 'txt'
      }
    }
  }
];

// ============================================================
// Prepare Scene MP4 Download v2.1
// Role:
// - Scene별 ComfyUI video download URL 생성
// - URLSearchParams 사용 제거
// - n8n Code Node VM 호환
// - filename / subfolder / type 기반 다운로드 준비
// ============================================================

const input =
  $input.first()?.json || {};

const files =
  input.files;

const config =
  $('Pipeline Config').first().json;

const expectedScenes =
  Number(config.video.scenes);


// ============================================================
// 1. 입력 검증
// ============================================================

if (!Array.isArray(files)) {
  throw new Error(
    'Create FFmpeg List의 files 배열이 없습니다.'
  );
}


if (
  files.length !== expectedScenes
) {
  throw new Error(
    `Video 파일 개수 오류: ` +
    `예상 ${expectedScenes}개 / ` +
    `실제 ${files.length}개`
  );
}


// ============================================================
// 2. Scene 순서 정렬
// ============================================================

const sorted =
  [...files].sort(
    (a, b) =>
      Number(a.scene) -
      Number(b.scene)
  );


// ============================================================
// 3. Download Item 생성
// ============================================================

return sorted.map(
  (file, index) => {

    const scene =
      Number(file.scene);

    const expectedScene =
      index + 1;


    // ----------------------------------------
    // Scene 번호 검증
    // ----------------------------------------

    if (
      !Number.isInteger(scene) ||
      scene !== expectedScene
    ) {
      throw new Error(
        `Scene 순서 오류: ` +
        `${expectedScene}번이 필요하지만 ` +
        `${scene}번이 들어왔습니다.`
      );
    }


    // ----------------------------------------
    // Filename 검증
    // ----------------------------------------

    const filename =
      typeof file.filename === 'string'
        ? file.filename.trim()
        : '';


    if (!filename) {
      throw new Error(
        `Scene ${scene}: filename이 없습니다.`
      );
    }


    // ----------------------------------------
    // ComfyUI File Metadata
    // ----------------------------------------

    const subfolder =
      typeof file.subfolder === 'string'
        ? file.subfolder.trim()
        : '';

    const type =
      typeof file.type === 'string' &&
      file.type.trim()
        ? file.type.trim()
        : 'output';


    // ========================================================
    // 4. n8n VM 호환 Safe URL
    // URLSearchParams 대신 encodeURIComponent 사용
    // ========================================================

    let url =
      `http://host.docker.internal:8188/view` +
      `?filename=${encodeURIComponent(filename)}` +
      `&type=${encodeURIComponent(type)}`;


    if (subfolder) {
      url +=
        `&subfolder=${encodeURIComponent(subfolder)}`;
    }


    // ----------------------------------------
    // Output
    // ----------------------------------------

    return {
      json: {

        scene,

        filename,

        subfolder,

        type,

        prompt_id:
          file.prompt_id || '',

        url,

        run_id:
          config.run_id,

        run_name:
          config.run_name,

        pipeline_version:
          config.pipeline_version

      }
    };

  }
);

// ============================================================
// Generate SRT v3.0 - Continuous Narration Alignment
//
// Role:
// - 자막 원문은 Scene Splitter narration 사용
// - 실제 시간은 Whisper segment timestamp 사용
// - Scene 개수와 Whisper segment 개수 독립
// - 전체 텍스트 진행률을 기준으로 Scene timing 자동 배분
// - 긴 Scene 자막은 읽기 좋은 cue로 재분할
// - Whisper는 timing + QC 용도
// ============================================================


// ============================================================
// 1. Input
// ============================================================

const whisperInput =
  $input.first()?.json || {};

const segments =
  whisperInput.segments;

const sceneItems =
  $('Scene Splitter').all();


// ============================================================
// 2. Whisper Validation
// ============================================================

if (!Array.isArray(segments)) {
  throw new Error(
    'Whisper segments 배열이 없습니다.'
  );
}

if (segments.length === 0) {
  throw new Error(
    'Whisper transcription segment가 없습니다.'
  );
}


// ============================================================
// 3. Scene Validation
// ============================================================

if (
  !Array.isArray(sceneItems) ||
  sceneItems.length === 0
) {
  throw new Error(
    'Scene Splitter narration 데이터가 없습니다.'
  );
}


// ============================================================
// 4. Config
// ============================================================

const MAX_CHARS_PER_CUE = 18;

const MIN_CHARS_PER_PART = 6;


// ============================================================
// 5. Helpers
// ============================================================

function normalizeText(text) {

  return String(text || '')
    .replace(/\s+/g, ' ')
    .trim();
}


function normalizeForComparison(text) {

  return normalizeText(text)
    .toLowerCase()
    .replace(/[\s\p{P}\p{S}]+/gu, '');
}


function toSrtTime(seconds) {

  const safeSeconds =
    Math.max(
      0,
      Number(seconds) || 0
    );

  const ms =
    Math.round(
      safeSeconds * 1000
    );

  const h =
    Math.floor(
      ms / 3600000
    );

  const m =
    Math.floor(
      (ms % 3600000) / 60000
    );

  const s =
    Math.floor(
      (ms % 60000) / 1000
    );

  const milli =
    ms % 1000;

  return (
    `${String(h).padStart(2, '0')}:` +
    `${String(m).padStart(2, '0')}:` +
    `${String(s).padStart(2, '0')},` +
    `${String(milli).padStart(3, '0')}`
  );
}


// ============================================================
// 6. Subtitle Splitter
// ============================================================

function splitSubtitle(text) {

  const normalized =
    normalizeText(text);

  if (!normalized) {
    return [];
  }


  // ------------------------------------------
  // 짧은 문장
  // ------------------------------------------

  if (
    normalized.length <=
    MAX_CHARS_PER_CUE
  ) {
    return [
      normalized
    ];
  }


  // ------------------------------------------
  // 1차: 문장부호 기준
  // ------------------------------------------

  const punctuationParts =
    normalized
      .split(
        /(?<=[.!?。！？,，])\s*/
      )
      .map(
        part => part.trim()
      )
      .filter(Boolean);


  if (
    punctuationParts.length > 1
  ) {

    const result = [];

    let buffer = '';


    for (
      const part
      of punctuationParts
    ) {

      const candidate =
        buffer
          ? `${buffer} ${part}`
          : part;


      if (
        candidate.length <=
        MAX_CHARS_PER_CUE
      ) {

        buffer =
          candidate;

      } else {

        if (buffer) {
          result.push(
            buffer
          );
        }

        buffer =
          part;
      }
    }


    if (buffer) {

      result.push(
        buffer
      );
    }


    if (
      result.length > 1
    ) {

      return result;
    }
  }


  // ------------------------------------------
  // 2차: 공백 기준
  // ------------------------------------------

  const words =
    normalized.split(' ');


  if (
    words.length > 1
  ) {

    const result = [];

    let buffer = '';


    for (
      const word
      of words
    ) {

      const candidate =
        buffer
          ? `${buffer} ${word}`
          : word;


      if (
        candidate.length <=
        MAX_CHARS_PER_CUE
      ) {

        buffer =
          candidate;

      } else {

        if (
          buffer.length >=
          MIN_CHARS_PER_PART
        ) {

          result.push(
            buffer
          );
        }

        buffer =
          word;
      }
    }


    if (buffer) {

      result.push(
        buffer
      );
    }


    if (
      result.length > 1
    ) {

      return result;
    }
  }


  // ------------------------------------------
  // 3차: 강제 2분할
  // ------------------------------------------

  const midpoint =
    Math.floor(
      normalized.length / 2
    );

  let splitIndex =
    midpoint;


  for (
    let offset = 0;
    offset < 8;
    offset++
  ) {

    const left =
      midpoint - offset;

    const right =
      midpoint + offset;


    if (
      left > 0 &&
      normalized[left] === ' '
    ) {

      splitIndex =
        left;

      break;
    }


    if (
      right <
      normalized.length &&
      normalized[right] === ' '
    ) {

      splitIndex =
        right;

      break;
    }
  }


  const first =
    normalized
      .slice(
        0,
        splitIndex
      )
      .trim();


  const second =
    normalized
      .slice(
        splitIndex
      )
      .trim();


  if (
    first &&
    second
  ) {

    return [
      first,
      second
    ];
  }


  return [
    normalized
  ];
}


// ============================================================
// 7. Scene Narration 정규화
// ============================================================

const scenes = [];


for (
  let index = 0;
  index < sceneItems.length;
  index++
) {

  const json =
    sceneItems[index]?.json || {};

  const scene =
    Number(
      json.scene
    );

  const expectedScene =
    index + 1;


  if (
    !Number.isInteger(scene) ||
    scene !== expectedScene
  ) {

    throw new Error(
      `Scene 순서 오류: ` +
      `${expectedScene}번 필요 / 실제 ${scene}`
    );
  }


  const narration =
    normalizeText(
      json.narration
    );


  if (!narration) {

    throw new Error(
      `Scene ${scene}: narration이 없습니다.`
    );
  }


  const comparisonText =
    normalizeForComparison(
      narration
    );


  if (!comparisonText) {

    throw new Error(
      `Scene ${scene}: 비교 가능한 narration 문자열이 없습니다.`
    );
  }


  scenes.push({

    scene,

    narration,

    comparison_text:
      comparisonText,

    comparison_length:
      comparisonText.length

  });
}


// ============================================================
// 8. Whisper Segment 정규화
// ============================================================

const whisperSegments = [];

let whisperCharacterCursor = 0;


for (
  let index = 0;
  index < segments.length;
  index++
) {

  const segment =
    segments[index] || {};

  const start =
    Number(
      segment.start
    );

  const end =
    Number(
      segment.end
    );


  if (
    !Number.isFinite(start) ||
    !Number.isFinite(end)
  ) {

    throw new Error(
      `Whisper segment ${index + 1}: ` +
      `timestamp가 올바르지 않습니다.`
    );
  }


  if (
    end <= start
  ) {

    throw new Error(
      `Whisper segment ${index + 1}: ` +
      `end <= start`
    );
  }


  const text =
    normalizeText(
      segment.text
    );


  const comparisonText =
    normalizeForComparison(
      text
    );


  const length =
    comparisonText.length;


  whisperSegments.push({

    index,

    start,

    end,

    text,

    comparison_text:
      comparisonText,

    char_start:
      whisperCharacterCursor,

    char_end:
      whisperCharacterCursor +
      length,

    char_length:
      length

  });


  whisperCharacterCursor +=
    length;
}


// ============================================================
// 9. 전체 길이 계산
// ============================================================

const plannerCharacterCount =
  scenes.reduce(
    (sum, scene) =>
      sum +
      scene.comparison_length,
    0
  );


const whisperCharacterCount =
  whisperCharacterCursor;


if (
  plannerCharacterCount <= 0
) {

  throw new Error(
    'Planner narration 문자 길이가 0입니다.'
  );
}


if (
  whisperCharacterCount <= 0
) {

  throw new Error(
    'Whisper 인식 문자열 길이가 0입니다.'
  );
}


// ============================================================
// 10. Whisper Character Position → 실제 시간
// ============================================================

function characterPositionToTime(
  position
) {

  const safePosition =
    Math.max(
      0,
      Math.min(
        position,
        whisperCharacterCount
      )
    );


  // ------------------------------------------
  // 처음
  // ------------------------------------------

  if (
    safePosition <= 0
  ) {

    return whisperSegments[0].start;
  }


  // ------------------------------------------
  // 마지막
  // ------------------------------------------

  if (
    safePosition >=
    whisperCharacterCount
  ) {

    return whisperSegments[
      whisperSegments.length - 1
    ].end;
  }


  // ------------------------------------------
  // 해당 Whisper segment 탐색
  // ------------------------------------------

  for (
    const segment
    of whisperSegments
  ) {

    if (
      segment.char_length <= 0
    ) {

      continue;
    }


    if (
      safePosition >=
        segment.char_start &&
      safePosition <=
        segment.char_end
    ) {

      const localPosition =
        safePosition -
        segment.char_start;


      const ratio =
        localPosition /
        segment.char_length;


      return (
        segment.start +
        (
          segment.end -
          segment.start
        ) *
        ratio
      );
    }
  }


  return whisperSegments[
    whisperSegments.length - 1
  ].end;
}


// ============================================================
// 11. Scene Timing 생성
// ============================================================

const sceneTimings = [];

let plannerCharacterCursor = 0;


for (
  let index = 0;
  index < scenes.length;
  index++
) {

  const scene =
    scenes[index];


  const plannerStart =
    plannerCharacterCursor;


  const plannerEnd =
    plannerCharacterCursor +
    scene.comparison_length;


  const whisperStartPosition =
    (
      plannerStart /
      plannerCharacterCount
    ) *
    whisperCharacterCount;


  const whisperEndPosition =
    (
      plannerEnd /
      plannerCharacterCount
    ) *
    whisperCharacterCount;


  let start =
    characterPositionToTime(
      whisperStartPosition
    );


  let end =
    characterPositionToTime(
      whisperEndPosition
    );


  // ------------------------------------------
  // 최소 시간 방어
  // ------------------------------------------

  if (
    !Number.isFinite(start) ||
    !Number.isFinite(end)
  ) {

    throw new Error(
      `Scene ${scene.scene}: timing 계산 실패`
    );
  }


  if (
    end <= start
  ) {

    end =
      start + 0.5;
  }


  sceneTimings.push({

    ...scene,

    start,

    end

  });


  plannerCharacterCursor =
    plannerEnd;
}


// ============================================================
// 12. Subtitle Cue 생성
// ============================================================

const cues = [];


for (
  const scene
  of sceneTimings
) {

  const parts =
    splitSubtitle(
      scene.narration
    );


  if (
    parts.length === 0
  ) {

    continue;
  }


  const comparisonLengths =
    parts.map(
      part =>
        Math.max(
          1,
          normalizeForComparison(
            part
          ).length
        )
    );


  const totalLength =
    comparisonLengths.reduce(
      (sum, value) =>
        sum + value,
      0
    );


  let currentStart =
    scene.start;


  for (
    let index = 0;
    index < parts.length;
    index++
  ) {

    const part =
      parts[index];


    const isLast =
      index ===
      parts.length - 1;


    const ratio =
      comparisonLengths[index] /
      totalLength;


    let partEnd =
      isLast
        ? scene.end
        : currentStart +
          (
            scene.end -
            scene.start
          ) *
          ratio;


    // 최소 표시 시간

    if (
      !isLast &&
      partEnd -
      currentStart <
      0.7
    ) {

      partEnd =
        Math.min(
          currentStart + 0.7,
          scene.end
        );
    }


    if (
      partEnd >
      currentStart
    ) {

      cues.push({

        scene:
          scene.scene,

        start:
          currentStart,

        end:
          partEnd,

        text:
          part

      });
    }


    currentStart =
      partEnd;
  }
}


// ============================================================
// 13. Cue Validation
// ============================================================

if (
  cues.length === 0
) {

  throw new Error(
    '유효한 subtitle cue가 없습니다.'
  );
}


// ============================================================
// 14. SRT 생성
// ============================================================

const srtBlocks =
  cues.map(
    (cue, index) =>

      `${index + 1}\n` +

      `${toSrtTime(cue.start)} --> ` +
      `${toSrtTime(cue.end)}\n` +

      `${cue.text}`
  );


const srt =
  srtBlocks.join(
    '\n\n'
  ) +
  '\n';


// ============================================================
// 15. 전체 Whisper QC
// ============================================================

