  scenes
    .map(
      scene =>
        scene.narration
    )
    .join(' ');


const whisperFullText =
  whisperSegments
    .map(
      segment =>
        segment.text
    )
    .join(' ');


const plannerComparison =
  normalizeForComparison(
    plannerFullText
  );


const whisperComparison =
  normalizeForComparison(
    whisperFullText
  );


const fullRawMatch =
  normalizeText(
    plannerFullText
  ) ===
  normalizeText(
    whisperFullText
  );


const fullMeaningfulMatch =
  plannerComparison ===
  whisperComparison;


