// ============================================================
// Scene Splitter v2.0
// - splits validated visual plan into n8n scene items
// - narration originates from deterministic Scene Adapter
// ============================================================
const config = $('Pipeline Config').first().json;
const plan = $input.first()?.json || {};
if (plan.stage !== 'visual_plan_validated') throw new Error('Scene Splitter: Visual Prompt Validator 출력이 아닙니다.');
if (!Array.isArray(plan.scenes)) throw new Error('Scene Splitter: scenes 배열이 없습니다.');
const expectedScenes = Number(config.video.scenes);
if (plan.scenes.length !== expectedScenes) throw new Error(`Scene 개수 오류: 예상 ${expectedScenes} / 실제 ${plan.scenes.length}`);
return plan.scenes.map((scene,index)=>{
  const sceneNumber = Number(scene.scene);
  if (!Number.isInteger(sceneNumber) || sceneNumber !== index+1) throw new Error(`Scene 순서 오류: 예상 ${index+1} / 실제 ${scene.scene}`);
  for (const field of ['narration','subtitle','image_prompt','motion_prompt']) {
    if (typeof scene[field] !== 'string' || !scene[field].trim()) throw new Error(`Scene ${sceneNumber}: ${field} 값이 없습니다.`);
  }
  return {json:{
    scene:sceneNumber,
    narration:scene.narration.trim(), subtitle:scene.subtitle.trim(),
    image_prompt:scene.image_prompt.trim(), motion_prompt:scene.motion_prompt.trim(),
    title:plan.title || '', script_summary:plan.script_summary || '', bgm_direction:plan.bgm_direction || {},
    run_id:config.run_id, run_name:config.run_name, pipeline_version:config.pipeline_version
  }};
});

// ============================================================
// Visual Prompt Validator v1.0
// - validates visual-only LLM output
// - narration/subtitle are restored ONLY from deterministic Scene Adapter
// ============================================================
const input = $input.first()?.json || {};
if (input.done !== true) throw new Error('Visual Prompt Validator: Ollama 응답이 완료되지 않았습니다.');
let raw = typeof input.message?.content === 'string' ? input.message.content.trim() : '';
if (!raw) throw new Error('Visual Prompt Validator: message.content가 비어 있습니다.');
raw = raw.replace(/```json/gi,'').replace(/```/g,'').trim();
let plan;
try { plan = JSON.parse(raw); } catch(e) { throw new Error('Visual Prompt JSON 파싱 실패: ' + e.message); }
if (!plan || typeof plan !== 'object' || Array.isArray(plan)) throw new Error('Visual Prompt 출력은 JSON 객체여야 합니다.');
if (plan.visual_plan_version !== '1.0') throw new Error('Visual Prompt version 오류');
if (!['PASS','WARN'].includes(plan.status)) throw new Error('Visual Prompt status 오류');
if (!Array.isArray(plan.scenes)) throw new Error('Visual Prompt scenes 배열이 없습니다.');

const source = $('Scene Adapter').first().json;
const sourceScenes = Array.isArray(source.scenes) ? source.scenes : [];
if (plan.scenes.length !== sourceScenes.length) throw new Error(`Visual Scene 개수 오류: 예상 ${sourceScenes.length} / 실제 ${plan.scenes.length}`);
const forbiddenTechnicalFields = ['frames','fps','width','height','resolution','checkpoint','steps','cfg','sampler','scheduler','seed','model','model_name'];
const merged = [];
for (let i=0; i<sourceScenes.length; i++) {
  const v = plan.scenes[i] || {};
  const s = sourceScenes[i] || {};
  const expected = i+1;
  if (Number(v.scene) !== expected || Number(s.scene) !== expected) throw new Error(`Visual Scene 순서 오류: ${expected}`);
  const imagePrompt = typeof v.image_prompt === 'string' ? v.image_prompt.trim() : '';
  const motionPrompt = typeof v.motion_prompt === 'string' ? v.motion_prompt.trim() : '';
  if (!imagePrompt || !motionPrompt) throw new Error(`Scene ${expected}: image/motion prompt가 없습니다.`);
  if (/[^\x00-\x7F]/.test(imagePrompt)) throw new Error(`Scene ${expected}: image_prompt는 English ASCII only여야 합니다.`);
  if (/[^\x00-\x7F]/.test(motionPrompt)) throw new Error(`Scene ${expected}: motion_prompt는 English ASCII only여야 합니다.`);
  for (const key of forbiddenTechnicalFields) if (Object.prototype.hasOwnProperty.call(v,key)) throw new Error(`Scene ${expected}: technical field 금지: ${key}`);
  merged.push({ scene:expected, narration:s.narration, subtitle:s.subtitle, image_prompt:imagePrompt, motion_prompt:motionPrompt });
}
const config = $('Pipeline Config').first().json;
return [{json:{
  stage:'visual_plan_validated', visual_plan_version:'1.0',
  title:source.title, script_summary:source.script_summary, full_narration:source.full_narration,
  bgm_direction:source.bgm_direction, scenes:merged, status:plan.status,
  run_id:config.run_id, run_name:config.run_name, pipeline_version:config.pipeline_version
}}];

// ============================================================
// Video Ready v3.0 - Pipeline Config v2.0 Runtime
// Role:
// - Run별 final_output.mp4 생성 완료 신호
// - Dynamic Runtime의 total_duration 기준 사용
// - Scene 수 / Scene 길이 / 총 길이 일관성 검증
// ============================================================

const config =
  $('Pipeline Config').first().json;

const input =
  $input.first()?.json || {};


// ============================================================
// 1. Runtime Values
// ============================================================

const sceneCount =
  Number(config.video.scenes);

const secondsPerScene =
  Number(config.video.seconds_per_scene);

const targetDuration =
  Number(config.video.total_duration);


// ============================================================
// 2. Config Validation
// ============================================================

if (
  !Number.isInteger(sceneCount) ||
  sceneCount <= 0
) {
  throw new Error(
    'Pipeline Config.video.scenes 값이 올바르지 않습니다.'
  );
}

if (
  !Number.isFinite(secondsPerScene) ||
  secondsPerScene <= 0
) {
  throw new Error(
    'Pipeline Config.video.seconds_per_scene 값이 올바르지 않습니다.'
  );
}

if (
  !Number.isFinite(targetDuration) ||
  targetDuration <= 0
) {
  throw new Error(
    'Pipeline Config.video.total_duration 값이 올바르지 않습니다.'
  );
}


// ============================================================
// 3. Runtime Consistency Check
// ============================================================

const calculatedDuration =
  sceneCount *
  secondsPerScene;

const durationDifference =
  Math.abs(
    calculatedDuration -
    targetDuration
  );


// 소수점 계산 오차만 허용
const DURATION_TOLERANCE =
  0.001;

if (
  durationDifference >
  DURATION_TOLERANCE
) {
  throw new Error(
    `Video Runtime 불일치: ` +
    `sceneCount × secondsPerScene = ${calculatedDuration}, ` +
    `total_duration = ${targetDuration}`
  );
}


// ============================================================
// 4. FFmpeg Result Validation
// ============================================================

if (
  input.exitCode !== undefined &&
  Number(input.exitCode) !== 0
) {
  throw new Error(
    `Video concat FFmpeg 실패: exitCode=${input.exitCode}`
  );
}


// ============================================================
// 5. Ready Signal
// ============================================================

return [
  {
    json: {

      asset_type:
        'video',

      video_ready:
        true,

      video_path:
        config.paths.final_scene_video,

      scene_count:
        sceneCount,

      seconds_per_scene:
        secondsPerScene,

      target_duration:
        targetDuration,

      calculated_duration:
        calculatedDuration,

      runtime_consistent:
        true,

      run_id:
        config.run_id,

      run_folder:
        config.paths.run_folder,

      run_name:
        config.run_name,

      pipeline_version:
        config.pipeline_version,

      source_scene_duration:
        Number(config.runtime.source_scene_duration),

      generated_source_duration:
        Number(config.runtime.generated_total_duration),

      status:
        'Pipeline Config v2.0 video ready'

    }
  }
];

