// Subtitle Ready v2.1 - Continuous Narration
// Role:
// - subtitle.srt 생성 완료 신호
// - Continuous narration 구조 대응
// - 영상 목표 길이와 실제 subtitle timing을 분리
// ============================================================

const config =
  $('Pipeline Config').first().json;

const input =
  $input.first()?.json || {};

const sceneCount =
  Number(config.video.scenes);

const targetVideoDuration =
  Number(config.video.total_duration);


// ============================================================
// 1. Config Validation
// ============================================================

if (
  !Number.isInteger(sceneCount) ||
  sceneCount <= 0
) {
  throw new Error(
    'Pipeline Config.video.scenes 값이 올바르지 않습니다.'
  );
}

if (
  !Number.isFinite(targetVideoDuration) ||
  targetVideoDuration <= 0
) {
  throw new Error(
    'Pipeline Config.video.total_duration 값이 올바르지 않습니다.'
  );
}


// ============================================================
// 2. Subtitle Verification Result
// ============================================================

if (
  input.exitCode !== undefined &&
  Number(input.exitCode) !== 0
) {
  throw new Error(
    `Subtitle verification 실패: exitCode=${input.exitCode}`
  );
}


// ============================================================
// 3. Ready Signal
// ============================================================

return [
  {
    json: {

      asset_type:
        'subtitle',

      subtitle_ready:
        true,

      subtitle_mode:
        'continuous_narration',

      subtitle_path:
        config.paths.subtitle,

      target_video_duration:
        targetVideoDuration,

      scene_count:
        sceneCount,

      run_id:
        config.run_id,

      run_folder:
        config.paths.run_folder,

      run_name:
        config.run_name,

      pipeline_version:
        config.pipeline_version,

      status:
        'Run-specific continuous narration subtitle ready'

    }
  }
];

// ============================================================
// Map ComfyUI Prompt ID v2.0
// Role:
// - HTTP Request2의 ComfyUI prompt_id
// - Prompt Engine v3.1의 원본 Scene metadata
// 를 정확히 다시 결합
// ============================================================

const config =
  $('Pipeline Config').first().json;

const responses =
  $input.all();

const sourceScenes =
  $('Prompt Engine v3.1').all();

const expectedScenes =
  Number(config.video.scenes);


// ============================================================
// 1. 기본 검증
// ============================================================

if (
  !Array.isArray(responses) ||
  responses.length !== expectedScenes
) {
  throw new Error(
    `ComfyUI response 개수 오류: ` +
    `예상 ${expectedScenes}개 / ` +
    `실제 ${responses?.length || 0}개`
  );
}


if (
  !Array.isArray(sourceScenes) ||
  sourceScenes.length !== expectedScenes
) {
  throw new Error(
    `Prompt Engine Scene 개수 오류: ` +
    `예상 ${expectedScenes}개 / ` +
    `실제 ${sourceScenes?.length || 0}개`
  );
}


// ============================================================
// 2. Prompt ID ↔ Scene 결합
// ============================================================

const usedPromptIds =
  new Set();


return responses.map(
  (responseItem, index) => {

    const response =
      responseItem.json || {};

    const source =
      sourceScenes[index]?.json || {};


    const promptId =
      response.prompt_id;


    const scene =
      Number(source.scene);


    // ----------------------------------------
    // prompt_id 검증
    // ----------------------------------------

    if (
      typeof promptId !== 'string' ||
      !promptId.trim()
    ) {
      throw new Error(
        `Scene ${index + 1}: ComfyUI prompt_id가 없습니다.`
      );
    }


    if (
      usedPromptIds.has(promptId)
    ) {
      throw new Error(
        `중복 ComfyUI prompt_id: ${promptId}`
      );
    }


    usedPromptIds.add(promptId);


    // ----------------------------------------
    // Scene 검증
    // ----------------------------------------

    if (
      !Number.isInteger(scene) ||
      scene !== index + 1
    ) {
      throw new Error(
        `Scene mapping 오류: ` +
        `index ${index + 1} / scene ${scene}`
      );
    }


    // ----------------------------------------
    // Output
    // ----------------------------------------

    return {
      json: {

        scene,

        prompt_id:
          promptId.trim(),

        narration:
          source.narration || '',

        subtitle:
          source.subtitle || '',

        image_prompt:
          source.image_prompt || '',

        motion_prompt:
          source.motion_prompt || '',

        image_positive_prompt:
          source.image_positive_prompt || '',

        video_positive_prompt:
          source.video_positive_prompt || '',

        run_name:
          config.run_name,

        pipeline_version:
          config.pipeline_version,

        status:
          `Scene ${scene} submitted to ComfyUI`

      },

      pairedItem: {
        item: index
      }

    };

  }
);

// ============================================================
// ComfyUI History Tracker v3.0
// FLUX Anchor + LTX I2V
// ============================================================

const config = $('Pipeline Config').first().json;
const expectedTotalCount = Number(config.video.scenes);
if (!Number.isInteger(expectedTotalCount) || expectedTotalCount <= 0) {
  throw new Error('Pipeline Config.video.scenes 값이 올바르지 않습니다.');
}

const mappedItems = $('Map ComfyUI Prompt ID').all();
if (!Array.isArray(mappedItems) || mappedItems.length !== expectedTotalCount) {
  throw new Error(`Prompt mapping 개수 오류: 예상 ${expectedTotalCount} / 실제 ${mappedItems?.length || 0}`);
}

const promptSceneMap = new Map();
const targetPromptIds = [];
for (let i = 0; i < mappedItems.length; i++) {
  const j = mappedItems[i].json || {};
  const scene = Number(j.scene);
  const promptId = j.prompt_id;
  if (!Number.isInteger(scene) || scene !== i + 1) throw new Error(`Mapped Scene 순서 오류: ${scene}`);
  if (typeof promptId !== 'string' || !promptId.trim()) throw new Error(`Scene ${scene}: mapped prompt_id가 없습니다.`);
  if (promptSceneMap.has(promptId)) throw new Error(`중복 prompt_id: ${promptId}`);
  promptSceneMap.set(promptId, { scene, order: i + 1 });
  targetPromptIds.push(promptId);
}

let rawItems = $input.all();
if (!Array.isArray(rawItems) || rawItems.length === 0) rawItems = $('HTTP Request3').all();

const videoMap = new Map();

function collectMedia(nodeOutput) {
  const found = [];
  if (!nodeOutput || typeof nodeOutput !== 'object') return found;
  for (const [key, value] of Object.entries(nodeOutput)) {
    if (!Array.isArray(value)) continue;
    for (const media of value) {
      if (media && typeof media === 'object' && media.filename) {
        found.push({ ...media, _source_key: key });
      }
    }
  }
  return found;
}

for (const item of rawItems) {
  const result = item.json;
  if (!result || typeof result !== 'object') continue;
  for (const [promptId, history] of Object.entries(result)) {
    if (!targetPromptIds.includes(promptId)) continue;
    const outputs = history?.outputs;
    if (!outputs || typeof outputs !== 'object') continue;

    for (const [nodeId, nodeOutput] of Object.entries(outputs)) {
      for (const media of collectMedia(nodeOutput)) {
        const filename = String(media.filename || '');
        if (!/\.(mp4|mkv|webm|gif)$/i.test(filename)) continue;
        const sceneInfo = promptSceneMap.get(promptId);
        if (!sceneInfo) continue;
        const candidate = {
          ready: true,
          scene: sceneInfo.scene,
          order: sceneInfo.order,
          prompt_id: promptId,
          node_id: nodeId,
          filename,
          subfolder: media.subfolder || '',
          type: media.type || 'output',
          format: media.format || media._source_key || '',
          frame_rate: media.frame_rate || null,
          fullpath: media.fullpath || ''
        };
        const existing = videoMap.get(promptId);
        if (!existing || /\.mp4$/i.test(candidate.filename) || !/\.mp4$/i.test(existing.filename)) {
          videoMap.set(promptId, candidate);
        }
      }
    }
  }
}

const completedVideoCount = videoMap.size;
const staticData = $getWorkflowStaticData('global');
if (typeof staticData.retryCount !== 'number') staticData.retryCount = 0;
staticData.retryCount += 1;
const MAX_RETRIES = 180;

if (staticData.retryCount > MAX_RETRIES) {
  const retry = staticData.retryCount;
  staticData.retryCount = 0;
  throw new Error(`[ComfyUI Timeout] 완료 ${completedVideoCount}/${expectedTotalCount}, Retry ${retry}/${MAX_RETRIES}`);
}

if (completedVideoCount < expectedTotalCount) {
  return [{ json: {
    ready: false,
    expected_video_count: expectedTotalCount,
    completed_video_count: completedVideoCount,
    retry_count: staticData.retryCount,
    status: `Generating... ${completedVideoCount}/${expectedTotalCount}`
  }}];
}

staticData.retryCount = 0;
const sortedVideos = Array.from(videoMap.values()).sort((a,b) => a.order - b.order);
if (sortedVideos.length !== expectedTotalCount) {
  throw new Error(`Video 완료 개수 오류: ${sortedVideos.length}/${expectedTotalCount}`);
}

return sortedVideos.map(video => ({ json: {
  ready: true,
  scene: video.scene,
  prompt_id: video.prompt_id,
  media_type: 'video',
  node_id: video.node_id,
  filename: video.filename,
  subfolder: video.subfolder,
  type: video.type,
  format: video.format,
  frame_rate: video.frame_rate,
  fullpath: video.fullpath,
  status: `Scene ${video.scene} Video Ready`
}}));

// ============================================================
// Restore Video Scene Metadata v1.0
// Role:
// - Download Scene MP4 binary 응답에 Scene metadata 복구
// - Prepare Scene MP4 Download의 원본 순서와 다시 결합
// - Run별 저장 경로 생성
// ============================================================

const downloadedItems =
  $input.all();

const sourceItems =
  $('Prepare Scene MP4 Download').all();

const config =
  $('Pipeline Config').first().json;

const expectedScenes =
  Number(config.video.scenes);


// ============================================================
// 1. 기본 검증
// ============================================================

if (
  !Array.isArray(downloadedItems) ||
  downloadedItems.length !== expectedScenes
) {
  throw new Error(
    `Downloaded Video 개수 오류: ` +
    `예상 ${expectedScenes}개 / ` +
    `실제 ${downloadedItems?.length || 0}개`
  );
}


if (
  !Array.isArray(sourceItems) ||
  sourceItems.length !== expectedScenes
) {
  throw new Error(
    `Video Source 개수 오류: ` +
    `예상 ${expectedScenes}개 / ` +
    `실제 ${sourceItems?.length || 0}개`
  );
}


// ============================================================
// 2. Scene Metadata 복구
// ============================================================

return downloadedItems.map(
  (downloadedItem, index) => {

    const source =
      sourceItems[index]?.json || {};

    const scene =
      Number(source.scene);

    const filename =
      typeof source.filename === 'string'
        ? source.filename.trim()
        : '';


    if (
      !Number.isInteger(scene) ||
      scene !== index + 1
    ) {
      throw new Error(
        `Video Scene mapping 오류: ` +
        `index ${index + 1} / scene ${scene}`
      );
    }


    if (!filename) {
      throw new Error(
        `Scene ${scene}: filename이 없습니다.`
      );
    }


    if (
      !downloadedItem.binary ||
      !downloadedItem.binary.data
    ) {
      throw new Error(
        `Scene ${scene}: Video binary data가 없습니다.`
      );
    }


    const savePath =
      `${config.paths.scene_video_folder}/${filename}`;


    return {
      json: {

        scene,

        filename,

        save_path:
          savePath,

        subfolder:
          source.subfolder || '',

        type:
          source.type || 'output',

        prompt_id:
          source.prompt_id || '',

        run_id:
          config.run_id,

        run_name:
          config.run_name,

        pipeline_version:
          config.pipeline_version

      },

      binary: {
        data:
          downloadedItem.binary.data
      },

      pairedItem: {
        item: index
      }
    };

  }
);

// ============================================================
// Prompt Engine v3.1 - FLUX Anchor + LTX I2V Adapter
// ============================================================
// Role
// - validated visual scene output를 FLUX anchor prompt와 LTX motion prompt로 정규화
// - technical generation parameters는 생성하지 않음
// - fixed camera / stable geometry / single simple motion 정책 적용
// ============================================================

const config = $('Pipeline Config').first().json;
const inputItems = $input.all();
const expectedScenes = Number(config.video.scenes);

if (!Array.isArray(inputItems) || inputItems.length !== expectedScenes) {
  throw new Error(`Prompt Engine 입력 Scene 개수 오류: 예상 ${expectedScenes} / 실제 ${inputItems?.length || 0}`);
}

function clean(value) {
  return String(value || '')
    .replace(/[\r\n]+/g, ' ')
    .replace(/\s+/g, ' ')
    .replace(/\s+,/g, ',')
    .replace(/,+/g, ',')
    .trim();
}

function normalizeAnchorPrompt(value) {
  let p = clean(value);
  p = p
    .replace(/\b(camera pans?|camera tilts?|camera zooms?|dolly|tracking shot|orbit(?:ing)? camera|handheld camera)\b/gi, 'fixed camera')
    .replace(/\b(readable text|captions?|subtitles?|logos?|watermarks?|interface graphics?|UI)\b/gi, 'no readable text')
    .replace(/\s+/g, ' ')
    .trim();
  return p;
}

function normalizeMotionPrompt(value) {
  let p = clean(value);
  p = p
    .replace(/\b(camera pans?|camera tilts?|camera zooms?|dolly|tracking shot|orbit(?:ing)? camera|handheld camera)\b/gi, 'fixed camera')
    .replace(/\b(rapid|fast|jerky|jittery|sudden|aggressive)\b/gi, 'slow')
    .replace(/\s+/g, ' ')
    .trim();
  return p;
}

const anchorNegative = clean(config.comfyui.anchor_negative_prompt);
const videoNegative = clean(config.comfyui.video_negative_prompt);

return inputItems.map((item, index) => {
  const src = item.json || {};
  const scene = Number(src.scene);
  if (!Number.isInteger(scene) || scene !== index + 1) {
    throw new Error(`Prompt Engine Scene 순서 오류: 예상 ${index + 1} / 실제 ${src.scene}`);
  }

  const imagePrompt = normalizeAnchorPrompt(src.image_prompt);
  const motionPrompt = normalizeMotionPrompt(src.motion_prompt);
  if (!imagePrompt) throw new Error(`Scene ${scene}: image_prompt가 없습니다.`);
  if (!motionPrompt) throw new Error(`Scene ${scene}: motion_prompt가 없습니다.`);

  const imagePositivePrompt = [
    imagePrompt,
    'Cinematic 3D render with realistic materials and lighting.',
    'Vertical composition, one clear focal subject, stable anatomy and stable object geometry.',
    'Clean frame, no readable text, no labels, no logos, no interface graphics.'
  ].join(' ');

  const videoPositivePrompt = [
    imagePrompt,
    `Motion: ${motionPrompt}.`,
    'The camera remains fixed and steady.',
    'Motion is slow, smooth, continuous, and physically plausible.',
    'Preserve the same subject identity, anatomy, clothing, props, environment, lighting, and geometry throughout the clip.',
    'No sudden pose changes, no extra objects, no object duplication, no morphing, no flicker.'
  ].join(' ');

  return {
    json: {
      scene,
      narration: src.narration || '',
      subtitle: src.subtitle || '',
      image_prompt: imagePrompt,
      motion_prompt: motionPrompt,
      image_positive_prompt: imagePositivePrompt,
      image_negative_prompt: anchorNegative,
      video_positive_prompt: videoPositivePrompt,
      video_negative_prompt: videoNegative,
      anchor_filename_prefix: `AI_Video_Factory/${config.run_id}/scene_${String(scene).padStart(2,'0')}_anchor`,
      video_filename_prefix: `AI_Video_Factory/${config.run_id}/scene_${String(scene).padStart(2,'0')}_video`,
      run_id: config.run_id,
      run_name: config.run_name,
      pipeline_version: config.pipeline_version,
      workflow_profile: config.comfyui.workflow_profile
    },
    pairedItem: { item: index }
  };
});

// ============================================================
// Combine Narration v1.0
// Role:
// - Scene Splitter의 narration 전체를 하나의 연속 narration으로 결합
// - Scene 순서/개수 검증
// - CosyVoice TTS 1회 호출용 단일 item 생성
// ============================================================

const config =
  $('Pipeline Config').first().json;

const items =
  $input.all();

const expectedScenes =
  Number(config.video.scenes);


// ============================================================
// 1. 기본 검증
// ============================================================

if (
  !Array.isArray(items) ||
  items.length === 0
) {
  throw new Error(
    'Scene Splitter narration 데이터가 없습니다.'
  );
}

if (
  !Number.isInteger(expectedScenes) ||
  expectedScenes <= 0
) {
  throw new Error(
    'Pipeline Config.video.scenes 값이 올바르지 않습니다.'
  );
}

if (
  items.length !== expectedScenes
) {
  throw new Error(
    `Scene 개수 오류: ` +
    `예상 ${expectedScenes}개 / ` +
    `실제 ${items.length}개`
  );
}


// ============================================================
// 2. Scene 순서 정렬 + narration 검증
// ============================================================

const sorted =
  [...items].sort(
    (a, b) =>
      Number(a.json.scene) -
      Number(b.json.scene)
  );

const narrations = [];


for (
  let index = 0;
  index < sorted.length;
  index++
) {

  const json =
    sorted[index].json || {};

  const scene =
    Number(json.scene);

  const expectedScene =
    index + 1;

  if (
    !Number.isInteger(scene) ||
    scene !== expectedScene
  ) {
    throw new Error(
      `Scene 순서 오류: ` +
      `${expectedScene}번 필요 / 실제 ${scene}`
    );
  }

  const narration =
    typeof json.narration === 'string'
      ? json.narration.trim()
      : '';

  if (!narration) {
    throw new Error(
      `Scene ${scene}: narration이 없습니다.`
    );
  }

  narrations.push(narration);
}


// ============================================================
// 3. 연속 narration 생성
// ============================================================
//
// 문장 사이에는 줄바꿈 1개만 사용.
// CosyVoice가 장문 입력을 내부적으로 자연스럽게 chunking하도록 함.
// ============================================================

const combinedNarration =
  narrations.join('\n');

if (!combinedNarration.trim()) {
  throw new Error(
    '결합된 narration이 비어 있습니다.'
  );
}


// ============================================================
// 4. 단일 item 반환
// ============================================================

return [
  {
    json: {

      narration:
        combinedNarration,

      scene_count:
        expectedScenes,

      narration_count:
        narrations.length,

      run_id:
        config.run_id,

      run_name:
        config.run_name,

      pipeline_version:
        config.pipeline_version,

      tts_mode:
        'continuous_narration'

    }
  }
];

// ============================================================
// Create Continuous Narration Command v1.4
// Dynamic Duration Fit
// + Centralized Tempo Limits
// + Audio Format Normalization
//
// Role:
// - continuous_raw.wav 실제 길이를 ffprobe로 측정
// - 영상 목표 길이에 필요한 tempo 자동 계산
// - tempo 허용범위를 Pipeline Config에서 읽음
// - lead-in silence 추가
// - silence / voice sample format 통일
// - 최종 narration을 목표 영상 길이에 맞춤
// ============================================================

const config =
  $('Pipeline Config').first().json;


// ============================================================
// 1. Config
// ============================================================

const ttsFolder =
  config.paths.tts_folder;

const finalNarration =
  config.paths.final_narration;

const targetDuration =
  Number(config.video.total_duration);

const leadInSeconds =
  Number(config.tts.lead_in_seconds);

const MIN_TEMPO =
  Number(config.tts.min_tempo);

const MAX_TEMPO =
  Number(config.tts.max_tempo);


// ============================================================
// 2. Validation
// ============================================================

if (!ttsFolder) {
  throw new Error(
    'Pipeline Config.paths.tts_folder가 없습니다.'
  );
}

if (!finalNarration) {
  throw new Error(
    'Pipeline Config.paths.final_narration이 없습니다.'
  );
}

if (
  !Number.isFinite(targetDuration) ||
  targetDuration <= 0
) {
  throw new Error(
    'Pipeline Config.video.total_duration 값이 올바르지 않습니다.'
  );
}

if (
  !Number.isFinite(leadInSeconds) ||
  leadInSeconds < 0
) {
  throw new Error(
    'Pipeline Config.tts.lead_in_seconds 값이 올바르지 않습니다.'
  );
}

if (
  leadInSeconds >= targetDuration
) {
  throw new Error(
    'lead-in 시간이 전체 영상 길이보다 길거나 같습니다.'
  );
}

if (
  !Number.isFinite(MIN_TEMPO) ||
  MIN_TEMPO <= 0
) {
  throw new Error(
    'Pipeline Config.tts.min_tempo 값이 올바르지 않습니다.'
  );
}

if (
  !Number.isFinite(MAX_TEMPO) ||
  MAX_TEMPO <= 0
) {
  throw new Error(
    'Pipeline Config.tts.max_tempo 값이 올바르지 않습니다.'
  );
}

if (
  MIN_TEMPO >= MAX_TEMPO
) {
  throw new Error(
    'tts.min_tempo는 tts.max_tempo보다 작아야 합니다.'
  );
}


// ============================================================
// 3. Paths
// ============================================================

const rawNarration =
  `${ttsFolder}/continuous_raw.wav`;


// ============================================================
// 4. Available Speech Duration
// ============================================================

const availableSpeechDuration =
  targetDuration -
  leadInSeconds;


// ============================================================
// 5. FFmpeg / ffprobe Command
// ============================================================

const command =
`
set -e

RAW_FILE="${rawNarration}"
FINAL_FILE="${finalNarration}"

TARGET_DURATION=${targetDuration}
LEAD_IN=${leadInSeconds}
SPEECH_TARGET=${availableSpeechDuration}

MIN_TEMPO=${MIN_TEMPO}
MAX_TEMPO=${MAX_TEMPO}


# ------------------------------------------------------------
# 1. Input Validation
# ------------------------------------------------------------

if [ ! -s "$RAW_FILE" ]; then
  echo "ERROR: continuous narration WAV not found or empty"
  echo "FILE: $RAW_FILE"
  exit 1
fi


# ------------------------------------------------------------
# 2. Measure Raw Narration Duration
# ------------------------------------------------------------

RAW_DURATION=$(
  /usr/local/bin/ffprobe \\
    -v error \\
    -show_entries format=duration \\
    -of default=noprint_wrappers=1:nokey=1 \\
    "$RAW_FILE"
)

if [ -z "$RAW_DURATION" ]; then
  echo "ERROR: ffprobe could not read narration duration"
  exit 1
fi


# ------------------------------------------------------------
# 3. Calculate Required Tempo
# ------------------------------------------------------------

TEMPO=$(
  awk \\
    -v raw="$RAW_DURATION" \\
    -v target="$SPEECH_TARGET" \\
    'BEGIN {
      if (target <= 0) {
        exit 1
      }

      printf "%.6f", raw / target
    }'
)

if [ -z "$TEMPO" ]; then
  echo "ERROR: tempo calculation failed"
  exit 1
fi


# ------------------------------------------------------------
# 4. Tempo Safety Validation
# ------------------------------------------------------------

TEMPO_TOO_LOW=$(
  awk \\
    -v tempo="$TEMPO" \\
    -v minimum="$MIN_TEMPO" \\
    'BEGIN {
      print (tempo < minimum) ? 1 : 0
    }'
)

TEMPO_TOO_HIGH=$(
  awk \\
    -v tempo="$TEMPO" \\
    -v maximum="$MAX_TEMPO" \\
    'BEGIN {
      print (tempo > maximum) ? 1 : 0
    }'
)


echo "RAW_DURATION=$RAW_DURATION"
echo "TARGET_DURATION=$TARGET_DURATION"
echo "LEAD_IN=$LEAD_IN"
echo "SPEECH_TARGET=$SPEECH_TARGET"
echo "REQUIRED_TEMPO=$TEMPO"
echo "MIN_TEMPO=$MIN_TEMPO"
echo "MAX_TEMPO=$MAX_TEMPO"


if [ "$TEMPO_TOO_LOW" = "1" ]; then
  echo "ERROR: narration is too short"
  echo "Required tempo $TEMPO is below minimum $MIN_TEMPO"
  exit 1
fi


if [ "$TEMPO_TOO_HIGH" = "1" ]; then
  echo "ERROR: narration is too long"
  echo "Required tempo $TEMPO exceeds maximum $MAX_TEMPO"
  exit 1
fi


# ------------------------------------------------------------
# 5. Create Final Narration
# ------------------------------------------------------------
#
# Important:
# Both lead-in silence and CosyVoice WAV are normalized to:
#
# 24000 Hz
# mono
#
# BEFORE concat.
# ------------------------------------------------------------

/usr/local/bin/ffmpeg \\
  -y \\
  -f lavfi \\
  -t "$LEAD_IN" \\
  -i "anullsrc=r=24000:cl=mono" \\
  -i "$RAW_FILE" \\
  -filter_complex \\
  "[0:a]aformat=sample_rates=24000:channel_layouts=mono[silence];\\
[1:a]aformat=sample_rates=24000:channel_layouts=mono,atempo=$TEMPO[voice];\\
[silence][voice]concat=n=2:v=0:a=1,apad,atrim=0:$TARGET_DURATION,asetpts=N/SR/TB[outa]" \\
  -map "[outa]" \\
  -c:a libmp3lame \\
  -ar 44100 \\
  -ac 2 \\
  -b:a 192k \\
  "$FINAL_FILE"


# ------------------------------------------------------------
# 6. Final Validation
# ------------------------------------------------------------

if [ ! -s "$FINAL_FILE" ]; then
  echo "ERROR: final narration was not created"
  exit 1
fi


FINAL_DURATION=$(
  /usr/local/bin/ffprobe \\
    -v error \\
    -show_entries format=duration \\
    -of default=noprint_wrappers=1:nokey=1 \\
    "$FINAL_FILE"
)


echo "FINAL_DURATION=$FINAL_DURATION"
echo "SUCCESS: continuous narration duration fit complete"
`;


// ============================================================
// 6. Output
// ============================================================

return [
