]);


// ============================================================
// 14. Recursive Forbidden Key Check
// ============================================================

function checkForbiddenKeys(
  value,
  path = 'root'
) {

  if (
    value === null ||
    typeof value !== 'object'
  ) {
    return;
  }


  if (
    Array.isArray(value)
  ) {

    value.forEach(
      (item, index) => {

        checkForbiddenKeys(
          item,
          `${path}[${index}]`
        );

      }
    );

    return;
  }


  for (
    const key
    of Object.keys(value)
  ) {

    if (
      forbiddenKeys.has(key)
    ) {

      throw new Error(
        `Concept Grounding 역할 침범: ` +
        `${path}.${key}`
      );

    }


    checkForbiddenKeys(
      value[key],
      `${path}.${key}`
    );

  }

}


