// ============================================================
// Scene Adapter v1.0 - deterministic narration partition
// AI Video Factory
// ============================================================
// - validated script text is NEVER rewritten
// - partitions hook+narration into exactly runtime scene_count scenes
// - builds visual-planning request only; no new factual narration
// ============================================================

const input = $input.first()?.json || {};
if (input.stage !== 'script_validated') throw new Error('Scene Adapter: Script Validator 출력이 아닙니다.');
if (input.ready_for_scene_adapter !== true) throw new Error('Scene Adapter: scene 제작 가능 상태가 아닙니다.');
const config = $('Pipeline Config').first().json;
const sceneCount = Number(config.runtime?.scene_count ?? config.video?.scenes);
if (!Number.isInteger(sceneCount) || sceneCount <= 0) throw new Error('Scene Adapter: scene_count 오류');

const fullText = [input.hook, input.narration, input.closing]
  .filter(v => typeof v === 'string' && v.trim())
  .map(v => v.replace(/\s+/g,' ').trim())
  .join(' ')
  .replace(/\s+/g,' ')
  .trim();
if (!fullText) throw new Error('Scene Adapter: validated script text가 비어 있습니다.');

function partitionByWords(text, count) {
  const tokens = text.split(/\s+/).filter(Boolean);
  if (tokens.length < count) {
    // Extremely short script: preserve order and exact characters, split by character windows.
    const chars = [...text];
    const out = [];
    let cursor = 0;
    for (let i=0; i<count; i++) {
      const remain = chars.length - cursor;
      const slots = count - i;
      const take = Math.max(1, Math.ceil(remain / slots));
      out.push(chars.slice(cursor, cursor + take).join('').trim());
      cursor += take;
    }
    return out;
  }

  const out = [];
  let cursor = 0;
  for (let i=0; i<count; i++) {
    const remainingScenes = count - i;
    const remainingTokens = tokens.length - cursor;
    if (remainingScenes === 1) {
      out.push(tokens.slice(cursor).join(' '));
      break;
    }
    const minLeave = remainingScenes - 1;
    const maxTake = remainingTokens - minLeave;
    const remainingText = tokens.slice(cursor).join(' ');
    const targetChars = Math.max(1, remainingText.length / remainingScenes);
    let take = 1;
    let acc = tokens[cursor].length;
    while (take < maxTake && acc < targetChars) {
      acc += 1 + tokens[cursor + take].length;
      take++;
    }
    out.push(tokens.slice(cursor, cursor + take).join(' '));
    cursor += take;
  }
  return out;
}

function subtitleFromNarration(text) {
  const cleaned = String(text || '').replace(/\s+/g,' ').trim().replace(/[.!?。！？]+$/g,'');
  if (cleaned.length <= 18) return cleaned;
  const words = cleaned.split(' ');
  let out = '';
  for (const word of words) {
    const candidate = out ? `${out} ${word}` : word;
    if (candidate.length > 18) break;
    out = candidate;
  }
  return out || cleaned.slice(0,18);
}

const parts = partitionByWords(fullText, sceneCount);
if (parts.length !== sceneCount || parts.some(v => !v)) throw new Error('Scene Adapter: scene partition 실패');
const scenes = parts.map((narration, i) => ({ scene:i+1, narration, subtitle:subtitleFromNarration(narration) }));
const model = config.engines?.planner?.model || 'qwen2.5:14b-instruct-q4_K_M';

const systemPrompt = `
You are the Visual Scene Planner for a Korean informational Shorts pipeline.
The narration is already validated and must never be rewritten.
For each scene, create ONLY two English creative fields:
1) image_prompt: a stable FLUX anchor image description.
