const combinedGroundingText =
  [
    topicNormalized,
    ...ambiguities.map(item => {

      if (
        !item ||
        typeof item !== 'object'
      ) {
        return '';
      }

      return [
        item.resolved_as,
        item.note
      ]
        .filter(Boolean)
        .join(' ');

    })
  ]
    .filter(Boolean)
    .join(' ');


// Common technical terms already resolved by grounding
const technicalTerms = [];


if (
  /zoomies/i.test(combinedGroundingText)
) {
  technicalTerms.push('cat zoomies');
}


if (
  /FRAP/i.test(combinedGroundingText)
) {
  technicalTerms.push(
    'frenetic random activity periods'
  );
}


// ============================================================
// 7. Search Queries
// ============================================================

const queries = [];


// ------------------------------------------------------------
// Query 1
// Korean general evidence
// ------------------------------------------------------------

queries.push(
  `${topicNormalized} 원인 특징`
);


// ------------------------------------------------------------
// Query 2
// Korean veterinary / behavior
// ------------------------------------------------------------

queries.push(
  `${topicNormalized} 고양이 행동 수의학`
);


// ------------------------------------------------------------
// Query 3
// English expert terminology
// ------------------------------------------------------------

if (
  technicalTerms.length > 0
) {

  queries.push(
    `${technicalTerms.join(' ')} causes cat behavior veterinary`
  );

}


// ------------------------------------------------------------
// Query 4
// FRAP-specific
// ------------------------------------------------------------

if (
  /FRAP/i.test(combinedGroundingText)
) {

  queries.push(
    'cat FRAPs zoomies veterinary behavior'
  );

}


// ============================================================
// 8. Fallback Query
// ============================================================

if (
  queries.length < 3
) {

  queries.push(
    `${topicNormalized} behavior explanation`
  );

}


// ============================================================
// 9. Deduplicate / Clean
// ============================================================

const uniqueQueries =
  [
    ...new Set(
      queries
        .map(q =>
          q
            .replace(/\s+/g, ' ')
            .trim()
        )
        .filter(Boolean)
    )
  ]
    .slice(
      0,
