// ============================================================
// Evidence Query Splitter v1.0
// AI Video Factory
// ============================================================
// Role
// - Evidence Query Builder의 queries 배열을
//   검색 1건당 n8n item 1개로 분리
// - SearXNG Search가 각 Query를 자동 실행하도록 준비
// ============================================================


// ============================================================
// 1. Input
// ============================================================

const input =
  $input.first()?.json || {};


// ============================================================
// 2. Validation
// ============================================================

if (
  input.stage !==
