const normalizedQueries =
  [
    ...new Set(
      queries
        .map(query =>
          typeof query === 'string'
            ? query.replace(/\s+/g, ' ').trim()
            : ''
        )
        .filter(Boolean)
    )
  ];


// ============================================================
// 5. Output One Item Per Query
// ============================================================

return normalizedQueries.map(
