// ============================================================
// Evidence Pack Builder v1.2
// AI Video Factory
// ============================================================
// Role
// - 여러 SearXNG 검색 결과 병합
// - n8n Code Node에서 URL global 객체에 의존하지 않음
// - URL 중복 제거
// - 저품질 출처 감점
// - 수의학 / 의료 / 대학 / 공공기관 우선
// - 독립적인 4~6개 출처 선택
// - 사실을 직접 생성하지 않음
// ============================================================


// ============================================================
// 1. Search Results
// ============================================================

const searchItems =
  $input.all();


if (
  !Array.isArray(searchItems) ||
  searchItems.length === 0
) {
  throw new Error(
    'Evidence Pack Builder: SearXNG 검색 결과가 없습니다.'
  );
}


// ============================================================
// 2. Original Metadata
// ============================================================

const splitItems =
  $('Evidence Query Splitter').all();


if (
  !Array.isArray(splitItems) ||
  splitItems.length === 0
) {
  throw new Error(
    'Evidence Pack Builder: Evidence Query Splitter 데이터를 찾을 수 없습니다.'
  );
}


const meta =
  splitItems[0].json;


// ============================================================
// 3. Source Limits
// ============================================================

const minimumSources =
  Number(
    meta.source_policy?.minimum_sources ?? 2
  );


const targetSources =
  Number(
    meta.source_policy?.target_sources ?? 4
  );


const maximumSources =
  Number(
    meta.source_policy?.maximum_sources ?? 6
  );


// ============================================================
// 4. Safe String Helper
// ============================================================

function cleanString(value) {

  return typeof value === 'string'
    ? value.trim()
    : '';

}


// ============================================================
// 5. Domain Extractor
// ============================================================
// IMPORTANT:
// n8n Code Node에서 new URL()에 의존하지 않음.
// 순수 문자열 방식으로 hostname 추출.
// ============================================================

function getDomain(url) {

  const value =
    cleanString(url);


  if (!value) {
    return '';
  }


  const match =
    value.match(
      /^https?:\/\/([^\/?#]+)/i
    );


  if (
    !match ||
    !match[1]
  ) {
    return '';
  }


  let domain =
    match[1]
      .toLowerCase()
      .trim();


  // port 제거
  domain =
    domain.split(':')[0];


  // www. 제거
  domain =
    domain.replace(
      /^www\./,
      ''
    );


  return domain;

}


// ============================================================
// 6. Canonical URL
// ============================================================
// URL 객체 없이 기본적인 정규화만 수행.
// ============================================================

function canonicalUrl(url) {

  let value =
    cleanString(url);


  if (!value) {
    return '';
  }


  // fragment 제거
  value =
    value.split('#')[0];


  // 흔한 tracking parameter 제거
  const trackingParams = [
    'utm_source',
    'utm_medium',
    'utm_campaign',
    'utm_term',
    'utm_content'
  ];


  for (
    const param
    of trackingParams
  ) {

    const regexMiddle =
      new RegExp(
        `([?&])${param}=[^&]*&?`,
        'gi'
      );


    value =
      value.replace(
        regexMiddle,
        '$1'
      );

  }


  // ?& 정리
  value =
    value
      .replace('?&', '?')
      .replace(/&&+/g, '&')
      .replace(/[?&]$/, '');


  return value;

}


// ============================================================
// 7. SearXNG Payload Extractor
// ============================================================

function extractPayload(itemJson) {

  if (
    !itemJson ||
    typeof itemJson !== 'object'
  ) {
    return {};
  }


  // Direct
  if (
    Array.isArray(
      itemJson.results
    )
  ) {
    return itemJson;
  }


  // body object
  if (
    itemJson.body &&
    typeof itemJson.body === 'object' &&
    !Array.isArray(itemJson.body)
  ) {
    return itemJson.body;
  }


  // body JSON string
  if (
    typeof itemJson.body === 'string'
  ) {

    try {

      const parsed =
        JSON.parse(
          itemJson.body
        );


      if (
        parsed &&
        typeof parsed === 'object'
      ) {
        return parsed;
      }

    } catch {

      // ignore
    }

  }


  // data object
  if (
    itemJson.data &&
    typeof itemJson.data === 'object' &&
    !Array.isArray(itemJson.data)
  ) {
    return itemJson.data;
  }


  return itemJson;

}


// ============================================================
// 8. High Trust Domains
// ============================================================

const highTrustPatterns = [

  // Veterinary / Medical
  /(^|\.)vcahospitals\.com$/,
  /(^|\.)petmd\.com$/,
  /(^|\.)avma\.org$/,
  /(^|\.)aspca\.org$/,

  // Animal welfare
  /(^|\.)cats\.org\.uk$/,
  /(^|\.)bluecross\.org\.uk$/,
  /(^|\.)rvc\.ac\.uk$/,

  // Academic / government
  /\.edu$/,
  /\.edu\.[a-z]{2}$/,
  /\.ac\.[a-z]{2}$/,
  /\.gov$/,
  /\.gov\.[a-z]{2}$/

];


// ============================================================
// 9. Medium Trust Domains
// ============================================================

const mediumTrustPatterns = [

  /(^|\.)hillspet\.com$/,
  /(^|\.)royalcanin\.com$/,
  /(^|\.)purina\.com$/,
  /(^|\.)cornell\.edu$/,
  /(^|\.)fitpetmall\.com$/

];


// ============================================================
// 10. Low Trust Domains
// ============================================================

const lowTrustPatterns = [

  /(^|\.)tistory\.com$/,
  /(^|\.)blog\.naver\.com$/,
  /(^|\.)pinterest\./,
  /(^|\.)namu\.wiki$/,
  /(^|\.)brunch\.co\.kr$/,
  /(^|\.)facebook\.com$/,
  /(^|\.)instagram\.com$/,
  /(^|\.)youtube\.com$/,
  /(^|\.)reddit\.com$/

];


// ============================================================
// 11. Source Classification
// ============================================================

function classifySource(
  domain,
  title,
  content
) {

  const text =
    `${title} ${content}`
      .toLowerCase();


  const highTrust =
    highTrustPatterns.some(
      pattern =>
        pattern.test(domain)
    );


  if (highTrust) {

    return {

      tier:
        'A',

      base_score:
        100

    };

  }


  const mediumTrust =
    mediumTrustPatterns.some(
      pattern =>
        pattern.test(domain)
    );


  if (mediumTrust) {

    return {

      tier:
        'B',

      base_score:
        75

    };

  }


  if (
    /\.org$/.test(domain) &&
    (
      text.includes('veterinary') ||
      text.includes('veterinarian') ||
      text.includes('animal health')
    )
  ) {

    return {

      tier:
        'B',

      base_score:
        70

    };

  }


  const lowTrust =
    lowTrustPatterns.some(
      pattern =>
        pattern.test(domain)
    );


  if (lowTrust) {

    return {

      tier:
        'D',

      base_score:
        10

    };

  }


  return {

    tier:
      'C',

    base_score:
      40

  };

}


// ============================================================
// 12. Merge Search Results
// ============================================================

const sourceMap =
  new Map();


const debugSearchShapes =
  [];


const debugRejected =
  {

    no_url:
      0,

    no_title:
      0,

    no_domain:
      0,

    accepted:
      0

  };


for (
  let searchIndex = 0;
  searchIndex < searchItems.length;
  searchIndex++
) {

  const rawResponse =
    searchItems[searchIndex].json || {};


  const response =
    extractPayload(
      rawResponse
    );


  const query =
    cleanString(
      response.query
    );


  const results =
    Array.isArray(
      response.results
    )
      ? response.results
      : [];


  debugSearchShapes.push({

    index:
      searchIndex + 1,

    query:
      query || null,

    result_count:
      results.length,

    raw_keys:
      Object.keys(
        rawResponse
      ),

    payload_keys:
      Object.keys(
        response || {}
      )

  });


  for (
    const result
    of results
  ) {

    if (
      !result ||
      typeof result !== 'object'
    ) {
      continue;
    }


    const url =
      cleanString(
        result.url
      );


    const title =
      cleanString(
        result.title
      );


    const content =
      cleanString(
        result.content
      );


    // --------------------------------------------------------
    // Required result fields
    // --------------------------------------------------------

    if (!url) {

      debugRejected.no_url += 1;

      continue;
    }


    if (!title) {

      debugRejected.no_title += 1;

      continue;
    }


    // --------------------------------------------------------
    // URL normalize
    // --------------------------------------------------------

    const canonical =
      canonicalUrl(
        url
      );


    const domain =
      getDomain(
        canonical
      );


    if (!domain) {

      debugRejected.no_domain += 1;

      continue;
    }


    debugRejected.accepted += 1;


    // --------------------------------------------------------
    // Classification
    // --------------------------------------------------------

    const sourceClass =
      classifySource(
        domain,
        title,
        content
      );


    const engineScoreRaw =
      Number(
        result.score
      );


    const engineScore =
      Number.isFinite(
        engineScoreRaw
      )
        ? engineScoreRaw
        : 0;


    // --------------------------------------------------------
    // New Source
    // --------------------------------------------------------

    if (
      !sourceMap.has(
        canonical
      )
    ) {

      sourceMap.set(

        canonical,

        {

          url:
            canonical,

          domain,

          title,

          snippet:
            content,

          published_date:
            result.publishedDate ||
            result.pubdate ||
            null,

          engine:
            cleanString(
              result.engine
            ),

          source_tier:
            sourceClass.tier,

          base_score:
            sourceClass.base_score,

          engine_score:
            engineScore,

          query_support:
            1,

          matched_queries:
            query
              ? [query]
              : []

        }

      );

    } else {

      // ------------------------------------------------------
      // Existing Source
      // ------------------------------------------------------

      const existing =
        sourceMap.get(
          canonical
        );


      existing.query_support += 1;


      if (
        query &&
        !existing.matched_queries.includes(
          query
        )
      ) {

        existing.matched_queries.push(
          query
        );

      }


      existing.engine_score =
        Math.max(
          existing.engine_score,
          engineScore
        );


      if (
        content.length >
        existing.snippet.length
      ) {

        existing.snippet =
          content;

      }

    }

  }

}


// ============================================================
// 13. Score Sources
// ============================================================

const scoredSources =
  [...sourceMap.values()]
    .map(source => {

      let score =
        source.base_score;


      // 여러 검색 Query에서 발견된 경우
      score +=
        Math.min(
          source.query_support * 8,
          24
        );


      // SearXNG 자체 점수
      score +=
        Math.min(
          source.engine_score * 5,
          10
        );


      // snippet 부실 감점
      if (
        !source.snippet ||
        source.snippet.length < 40
      ) {

        score -= 10;

      }


      const combined =
        `${source.title} ${source.snippet}`
          .toLowerCase();


      // 전문 키워드 가점
      if (
        combined.includes(
          'veterinary'
        ) ||
        combined.includes(
          'veterinarian'
        )
      ) {

        score += 10;

      }


      // 주제 직접 관련 가점
      if (
        combined.includes(
          'zoomies'
        ) ||
        combined.includes(
          'frap'
        )
      ) {

        score += 5;

      }


      source.evidence_score =
        Number(
          score.toFixed(2)
        );


      return source;

    })
    .sort(
      (a, b) =>
        b.evidence_score -
        a.evidence_score
    );


// ============================================================
// 14. Select Independent Sources
// ============================================================

const selectedSources =
  [];


const usedDomains =
  new Set();


// ------------------------------------------------------------
// Pass 1
// A / B sources first
// ------------------------------------------------------------

for (
  const source
  of scoredSources
) {

  if (
    selectedSources.length >=
    maximumSources
  ) {
    break;
  }


  if (
    source.source_tier !== 'A' &&
    source.source_tier !== 'B'
  ) {
    continue;
  }


  if (
    usedDomains.has(
      source.domain
    )
  ) {
    continue;
  }


  selectedSources.push(
    source
  );


  usedDomains.add(
    source.domain
  );

}


// ------------------------------------------------------------
// Pass 2
// Fill with C sources
// ------------------------------------------------------------

if (
  selectedSources.length <
  targetSources
) {

  for (
    const source
    of scoredSources
  ) {

    if (
      selectedSources.length >=
      targetSources
    ) {
      break;
    }


    if (
      source.source_tier !== 'C'
    ) {
      continue;
    }


    if (
      usedDomains.has(
        source.domain
      )
    ) {
      continue;
    }


    selectedSources.push(
      source
    );


    usedDomains.add(
      source.domain
    );

  }

}


// ============================================================
// 15. Minimum Source Fallback
// ============================================================

if (
  selectedSources.length <
  minimumSources
) {

  for (
    const source
    of scoredSources
  ) {

    if (
      selectedSources.length >=
      minimumSources
    ) {
      break;
    }


    if (
      source.source_tier === 'D'
    ) {
      continue;
    }


    if (
      selectedSources.some(
        item =>
          item.url === source.url
      )
    ) {
      continue;
    }


    selectedSources.push(
      source
    );

  }

}


// ============================================================
// 16. Strong Source Count
// ============================================================

const strongSourceCount =
  selectedSources.filter(
    source =>
      source.source_tier === 'A' ||
      source.source_tier === 'B'
  ).length;


// ============================================================
// 17. Status
// ============================================================

let status =
  'PASS';


if (
  selectedSources.length <
  minimumSources
) {

  status =
    'FAIL';

} else if (
  strongSourceCount < 2
) {

  status =
    'WARN';

}


// ============================================================
// 18. Clean Evidence Output
// ============================================================

const evidence =
  selectedSources.map(
    (source, index) => {

      return {

        id:
          `E${index + 1}`,

        title:
          source.title,

        url:
          source.url,

        domain:
          source.domain,

        snippet:
          source.snippet,

        published_date:
          source.published_date,

        source_tier:
          source.source_tier,

        evidence_score:
          source.evidence_score,

        query_support:
          source.query_support,

        matched_queries:
          source.matched_queries

      };

    }
  );


// ============================================================
// 19. Output
// ============================================================

return [
  {
    json: {

      stage:
        'evidence_pack_ready',

      evidence_pack_version:
        '1.2',

      topic_original:
        meta.topic_original,

      topic_normalized:
        meta.topic_normalized,

      core_intent:
        meta.core_intent,

      risk_domain:
        meta.risk_domain,

      key_terms:
        meta.key_terms || [],

      ambiguities:
        meta.ambiguities || [],

      exclusions:
        meta.exclusions || [],


      // ======================================================
      // Temporary Debug
      // ======================================================

      search_debug:
        debugSearchShapes,

      filter_debug:
        debugRejected,


      // ======================================================
      // Summary
      // ======================================================

      search_summary: {

        query_count:
          searchItems.length,

        raw_result_count:
          debugRejected.accepted +
          debugRejected.no_url +
          debugRejected.no_title +
          debugRejected.no_domain,

        accepted_result_count:
          debugRejected.accepted,

        raw_source_count:
          sourceMap.size,

        selected_source_count:
          evidence.length,

        strong_source_count:
          strongSourceCount

      },


      // ======================================================
      // Evidence
      // ======================================================

      evidence,


      evidence_rules:
        meta.evidence_rules || {},


      status,


      ready_for_fact_pack:
        status === 'PASS' ||
        status === 'WARN',


      run_id:
        meta.run_id,

      run_name:
        meta.run_name,

      pipeline_version:
        meta.pipeline_version

    }
  }
];

// ============================================================
// Fact Pack Validator v1.6.2
// AI Video Factory
// ============================================================
// Main Guards
// - Schema / Evidence reference
// - Confidence / script_use
// - Exact support quote integrity
// - Claim ↔ Quote semantic coverage
// - Cross-language critical meaning guard
// - Behavior vs Change preservation
// - Advice blocking
// - Safe framing allowlist
// - Causal integrity
// ============================================================


// ============================================================
// 1. Input
// ============================================================

const ollamaResponse =
  $input.first()?.json || {};

if (
  !ollamaResponse ||
  typeof ollamaResponse !== 'object'
) {
  throw new Error(
    'Fact Pack Validator: Ollama 응답이 없습니다.'
  );
}

if (
  ollamaResponse.done !== true
) {
  throw new Error(
    'Fact Pack Validator: Ollama 응답이 완료되지 않았습니다.'
  );
}

const ollamaMessage =
  ollamaResponse.message;

if (
  !ollamaMessage ||
  typeof ollamaMessage !== 'object'
) {
  throw new Error(
    'Fact Pack Validator: message 객체가 없습니다.'
  );
}

let rawContent =
  typeof ollamaMessage.content === 'string'
    ? ollamaMessage.content.trim()
    : '';

if (!rawContent) {
  throw new Error(
    'Fact Pack Validator: message.content가 비어 있습니다.'
  );
}


// ============================================================
// 2. JSON Parse
// ============================================================

rawContent =
  rawContent
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

let factPack;

try {

  factPack =
    JSON.parse(rawContent);

} catch (error) {

  throw new Error(
    `Fact Pack Validator: JSON 파싱 실패 - ${error.message}`
  );
}


// ============================================================
// 3. Upstream
// ============================================================

const upstreamFactInput =
  $('Fact Pack Input').first().json;

if (
  !upstreamFactInput ||
  upstreamFactInput.stage !== 'fact_pack_input'
) {
  throw new Error(
    'Fact Pack Validator: Fact Pack Input 결과가 아닙니다.'
  );
}

const pipelineConfig =
  $('Pipeline Config').first().json;

const upstreamEvidence =
  Array.isArray(upstreamFactInput.evidence)
    ? upstreamFactInput.evidence
    : [];


// ============================================================
// 4. Helpers
// ============================================================

function cleanText(value) {

  return String(value || '')
    .replace(/\s+/g, ' ')
    .trim();
}


function normalizeText(value) {

  return cleanText(value)
    .toLowerCase();
}


function containsPattern(text, pattern) {

  return normalizeText(text)
    .includes(
      normalizeText(pattern)
    );
}


function uniqueStrings(values) {

  return [
    ...new Set(
      values
        .map(value => cleanText(value))
        .filter(Boolean)
    )
  ];
}


function getFactText(fact) {

  return cleanText(
    fact?.claim ??
    fact?.statement ??
    fact?.fact ??
    fact?.text ??
    ''
  );
}


function getFactEvidenceIds(fact) {

  const values =
    fact?.evidence_ids ??
    fact?.evidence_refs ??
    fact?.source_ids ??
    [];

  return uniqueStrings(
    Array.isArray(values)
      ? values
      : []
  );
}


function getEvidenceId(evidence) {

  return cleanText(
    evidence?.id ??
    evidence?.evidence_id ??
    evidence?.source_id ??
    ''
  );
}


function getEvidenceSnippet(evidence) {

  return cleanText(
    evidence?.snippet ??
    evidence?.text ??
    evidence?.content ??
    ''
  );
}


function detectLanguage(text) {

  const value =
    cleanText(text);

  const ko =
    value.match(/[가-힣]+/g) || [];

  const en =
    value.match(/[A-Za-z]+/g) || [];

  if (
    ko.length === 0 &&
    en.length === 0
  ) {
    return 'unknown';
  }

  if (
    ko.length > en.length
  ) {
    return 'ko';
  }

  if (
    en.length > ko.length
  ) {
    return 'en';
  }

  return 'mixed';
}


// ============================================================
// 5. Validation State
// ============================================================

const validationErrors = [];
const validationWarnings = [];

const failed = {

  structure: false,

  evidence_reference: false,

  confidence_policy: false,

  support_quote_integrity: false,

  claim_quote_coverage: false,

  qualifier_preservation: false,

  advice_boundary: false,

  safe_framing: false,

  role_boundary: false,

  causal_integrity: false

};


function addError(
  category,
  message
) {

  if (
    Object.prototype.hasOwnProperty.call(
      failed,
      category
    )
  ) {
    failed[category] = true;
  }

  validationErrors.push(
    message
  );
}


// ============================================================
// 6. Top-Level Schema
// ============================================================

const factPackVersion =
  cleanText(
    factPack.fact_pack_version
  );

const topicNormalized =
  cleanText(
    factPack.topic_normalized
  );

const coreIntent =
  cleanText(
    factPack.core_intent
  );

const riskDomain =
  cleanText(
    factPack.risk_domain
  );

const sourceStatus =
  cleanText(
    factPack.status
  ).toUpperCase();


if (
  factPackVersion !== '1.3'
) {

  addError(
    'structure',
    `지원하지 않는 fact_pack_version: ${factPackVersion}`
  );
}


if (!topicNormalized) {

  addError(
    'structure',
    'topic_normalized가 비어 있습니다.'
  );
}


if (!coreIntent) {

  addError(
    'structure',
    'core_intent가 비어 있습니다.'
  );
}


const allowedRiskDomains =
  new Set([
    'general',
    'science',
    'health',
    'finance',
    'legal',
    'safety'
  ]);


if (
  !allowedRiskDomains.has(
    riskDomain
  )
) {

  addError(
    'structure',
    `지원하지 않는 risk_domain: ${riskDomain}`
  );
}


// ============================================================
// 7. Evidence Map
// ============================================================

const evidenceMap =
  new Map();


for (
  const evidence
  of upstreamEvidence
) {

  const evidenceId =
    getEvidenceId(
      evidence
    );

  if (!evidenceId) {
    continue;
  }

  evidenceMap.set(
    evidenceId,
    evidence
  );
}


if (
  evidenceMap.size === 0
) {

  addError(
    'evidence_reference',
    '사용 가능한 upstream Evidence가 없습니다.'
  );
}


// ============================================================
// 8. Facts / Policy
// ============================================================

const facts =
  Array.isArray(factPack.facts)
    ? factPack.facts
    : [];


if (
  facts.length === 0
) {

  addError(
    'structure',
    'facts 배열이 비어 있습니다.'
  );
}


if (
  facts.length > 5
) {

  addError(
    'structure',
    `facts 개수 초과: ${facts.length} / 최대 5`
  );
}


const allowedConfidence =
  new Set([
    'HIGH',
    'MEDIUM',
    'LOW'
  ]);


const allowedScriptUse =
  new Set([
    'ALLOW',
    'QUALIFY',
    'AVOID'
  ]);


const seenFactIds =
  new Set();


for (
  let index = 0;
  index < facts.length;
  index++
) {

  const fact =
    facts[index] || {};

  const factId =
    cleanText(
      fact.id
    );

  const factText =
    getFactText(
      fact
    );

  const confidence =
    cleanText(
      fact.confidence
    ).toUpperCase();

  const scriptUse =
    cleanText(
      fact.script_use
    ).toUpperCase();

  const evidenceIds =
    getFactEvidenceIds(
      fact
    );


  if (!factId) {

    addError(
      'structure',
      `Fact ${index + 1}: id가 없습니다.`
    );

  } else if (
    seenFactIds.has(factId)
  ) {

    addError(
      'structure',
      `중복 Fact ID: ${factId}`
    );

  } else {

    seenFactIds.add(
      factId
    );
  }


  if (!factText) {

    addError(
      'structure',
      `${factId}: claim이 없습니다.`
    );
  }


  if (
    !allowedConfidence.has(
      confidence
    )
  ) {

    addError(
      'confidence_policy',
      `${factId}: 지원하지 않는 confidence: ${confidence}`
    );
  }


  if (
    !allowedScriptUse.has(
      scriptUse
    )
  ) {

    addError(
      'confidence_policy',
      `${factId}: 지원하지 않는 script_use: ${scriptUse}`
    );
  }


  if (
    confidence === 'MEDIUM' &&
    scriptUse === 'ALLOW'
  ) {

    addError(
      'confidence_policy',
      `${factId}: MEDIUM Fact는 ALLOW를 사용할 수 없습니다.`
    );
  }


  if (
    confidence === 'LOW' &&
    scriptUse !== 'AVOID'
  ) {

    addError(
      'confidence_policy',
      `${factId}: LOW Fact는 반드시 AVOID여야 합니다.`
    );
  }


  if (
    evidenceIds.length === 0
  ) {

    addError(
      'evidence_reference',
      `${factId}: evidence_ids가 없습니다.`
    );
  }


  for (
    const evidenceId
    of evidenceIds
  ) {

    if (
      !evidenceMap.has(
        evidenceId
      )
    ) {

      addError(
        'evidence_reference',
        `${factId}: 존재하지 않는 Evidence ID: ${evidenceId}`
      );
    }
  }


  if (
    confidence === 'HIGH' &&
    scriptUse === 'ALLOW' &&
    evidenceIds.length < 2
  ) {

    addError(
      'confidence_policy',
      `${factId}: HIGH + ALLOW는 최소 2개 Evidence가 필요합니다.`
    );
  }
}


// ============================================================
// 9. Exact Support Quote Integrity
// ============================================================

const supportQuoteChecks = [];


for (
  const fact
  of facts
) {

  const factId =
    cleanText(
      fact.id
    );

  const evidenceIds =
    getFactEvidenceIds(
      fact
    );

  const supportQuotes =
    Array.isArray(
      fact.support_quotes
    )
      ? fact.support_quotes
      : [];

  const checks = [];


  if (
    supportQuotes.length === 0
  ) {

    addError(
      'support_quote_integrity',
      `${factId}: support_quotes가 없습니다.`
    );
  }


  for (
    const item
    of supportQuotes
  ) {

    const evidenceId =
      cleanText(
        item?.evidence_id
      );

    const quote =
      cleanText(
        item?.quote
      );

    let valid = true;

    const reasons = [];


    if (
      !evidenceId ||
      !evidenceIds.includes(
        evidenceId
      )
    ) {

      valid = false;

      reasons.push(
        'Fact evidence_ids와 불일치'
      );

      addError(
        'support_quote_integrity',
        `${factId}: support quote Evidence ID 오류: ${evidenceId}`
      );
    }


    const evidence =
      evidenceMap.get(
        evidenceId
      );

    let quoteExists =
      false;


    if (
      evidence &&
      quote
    ) {

      quoteExists =
        normalizeText(
          getEvidenceSnippet(
            evidence
          )
        ).includes(
          normalizeText(
            quote
          )
        );
    }


    if (!quoteExists) {

      valid = false;

      reasons.push(
        'Evidence snippet 원문에 quote 없음'
      );

      addError(
        'support_quote_integrity',
        `${factId}: support quote가 ${evidenceId} 원문에 존재하지 않습니다.`
      );
    }


    checks.push({

      evidence_id:
        evidenceId,

      quote,

      quote_exists:
        quoteExists,

      valid,

      reasons

    });
  }


  supportQuoteChecks.push({

    fact_id:
      factId,

    valid:
      supportQuotes.length > 0 &&
      checks.every(
        check =>
          check.valid
      ),

    checks

  });
}


