const coverageChecks = [];

const coverageMap =
  new Map();


for (
  const fact
  of facts
) {

  const factId =
    cleanText(
      fact.id
    );

  const claim =
    getFactText(
      fact
    );

  const supportQuotes =
    Array.isArray(
      fact.support_quotes
    )
      ? fact.support_quotes
      : [];

  const quoteText =
    supportQuotes
      .map(item =>
        cleanText(
          item?.quote
        )
      )
      .filter(Boolean)
      .join(' ');


  const claimLanguage =
    detectLanguage(
      claim
    );

  const quoteLanguage =
    detectLanguage(
      quoteText
    );


  const crossLanguage =
    (
      claimLanguage === 'ko' &&
      quoteLanguage === 'en'
    ) ||
    (
      claimLanguage === 'en' &&
      quoteLanguage === 'ko'
    );


  const unsupportedPhrases = [];


  for (
    const rule
    of semanticRules
  ) {

    const claimUses =
      rule.claim_patterns
        .some(pattern =>

          containsPattern(
            claim,
            pattern
          )

        );


    if (!claimUses) {
      continue;
    }


    const quoteSupports =
      rule.quote_patterns
        .some(pattern =>

          containsPattern(
            quoteText,
            pattern
          )

        );


    if (!quoteSupports) {

      unsupportedPhrases.push(
        rule.label
      );
    }
  }


  // ----------------------------------------------------------
  // Same-language conservative word overlap
  // ----------------------------------------------------------

  let coverageRatio = null;
  let lexicalValid = true;


  if (!crossLanguage) {

    const claimWords =
      normalizeText(claim)
        .replace(
          /[^0-9a-z가-힣]+/gi,
          ' '
        )
        .split(/\s+/)
        .filter(word =>
          word.length >= 2
        );


    const quoteWords =
      normalizeText(quoteText)
        .replace(
          /[^0-9a-z가-힣]+/gi,
          ' '
        )
        .split(/\s+/)
        .filter(word =>
          word.length >= 2
        );


    const uniqueClaimWords =
      [
        ...new Set(
          claimWords
        )
      ];


    const matchingWords =
      uniqueClaimWords
        .filter(claimWord =>

          quoteWords.some(
            quoteWord =>

              quoteWord.includes(
                claimWord
              ) ||
              claimWord.includes(
                quoteWord
              )

          )

        );


    coverageRatio =
      matchingWords.length /
      Math.max(
        1,
        uniqueClaimWords.length
      );


    lexicalValid =
      coverageRatio >= 0.30;
  }


  const valid =
    unsupportedPhrases.length === 0 &&
    lexicalValid;


  const result = {

    fact_id:
      factId,

    mode:
      crossLanguage
        ? 'cross_language_guardrail'
        : 'same_language_lexical',

    claim_language:
      claimLanguage,

    quote_language:
      quoteLanguage,

    coverage_ratio:
      coverageRatio === null
        ? null
        : Number(
            coverageRatio.toFixed(3)
          ),

    unsupported_phrases:
      unsupportedPhrases,

    valid

  };


  coverageChecks.push(
    result
  );


  coverageMap.set(
    factId,
    result
  );


  if (
    unsupportedPhrases.length > 0
  ) {

    addError(
      'claim_quote_coverage',
      `${factId}: Claim의 의미 요소가 support_quotes에 없습니다: ${unsupportedPhrases.join(', ')}`
    );
  }


  if (
    !crossLanguage &&
    !lexicalValid
  ) {

    addError(
      'claim_quote_coverage',
      `${factId}: Claim과 support_quotes의 의미 범위 일치도가 부족합니다. coverage=${coverageRatio.toFixed(3)}`
    );
  }
}


