  '추천합니다',
  '권장합니다',

  '고려해야',
  '고려해 볼 필요',
  '고려할 필요',

  '병원에 가',
  '병원을 방문',

  '수의사에게',
  '수의사와 상담',

  '전문가에게',
  '전문가와 상담',

  '해야 합니다',
  '해야 한다',

  '할 필요가 있습니다',
  '할 필요가 있다'

];


const adviceChecks = [];


for (
  const uncertainty
  of uncertainties
) {

  const uncertaintyId =
    cleanText(
      uncertainty.id
    );

  const guidance =
    cleanText(
      uncertainty.guidance
    );


  const detected =
    advicePatterns
      .filter(pattern =>

        containsPattern(
          guidance,
          pattern
        )

      );


  const valid =
    detected.length === 0;


  adviceChecks.push({

    location:
      `uncertainty:${uncertaintyId}:guidance`,

    text:
      guidance,

    detected,

    valid

  });


  if (!valid) {

    addError(
      'advice_boundary',
      `${uncertaintyId}: guidance에 권고/조언 표현이 포함되었습니다: ${detected.join(', ')}`
    );
  }
}


// ============================================================
// 13. Safe Framing v1.6.2
// ============================================================
//
// safe_framing은 새로운 사실 생성 영역이 아님.
// 아래 중립 문구만 허용.
// ============================================================

const prohibitedClaims =
  Array.isArray(
    factPack.prohibited_claims
  )
    ? factPack.prohibited_claims
    : [];


const safeFraming =
  Array.isArray(
    factPack.safe_framing
  )
    ? factPack.safe_framing
    : [];


const allowedSafeFraming = new Set([

  '평소와 다르게 변했다면',

  '~일 수 있다',

  '~와 관련될 수 있다',

  '원인은 확정할 수 없다',

  '가능성 표현을 유지한다',

  '변화 조건을 유지한다',

  '행동 자체와 행동의 변화를 구분한다',

  '단정 표현을 피한다'

]);


const safeFramingChecks = [];


for (
  const value
  of safeFraming
) {

  const normalizedValue =
    cleanText(
      value
    );


  const valid =
    allowedSafeFraming.has(
      normalizedValue
    );


  safeFramingChecks.push({

    text:
      normalizedValue,

    valid

  });


  if (!valid) {

    addError(
      'safe_framing',
      `허용되지 않은 safe_framing 표현: ${normalizedValue}`
    );
  }
}


// ============================================================
// 14. Role Boundary
// ============================================================

const forbiddenKeys =
  new Set([

    'scenes',
    'scene',

    'hook',
    'narration',
    'closing',
    'script',

    'subtitle',

    'image_prompt',
    'motion_prompt',

    'positive_prompt',
    'negative_prompt',

    'camera',
    'lighting',

    'width',
    'height',
    'frames',
    'fps',
    'cfg',
    'steps',
    'sampler'

  ]);


function scanForbiddenKeys(
  value,
  path = 'root'
) {

  if (
    !value ||
    typeof value !== 'object'
  ) {
    return;
  }


  if (
    Array.isArray(value)
  ) {

    value.forEach(
      (child, index) =>

        scanForbiddenKeys(
          child,
          `${path}[${index}]`
        )
    );

    return;
  }


  for (
    const [key, child]
    of Object.entries(value)
  ) {

    if (
      forbiddenKeys.has(
        key
      )
    ) {

      addError(
        'role_boundary',
        `역할 침범 필드 감지: ${path}.${key}`
      );
    }


    scanForbiddenKeys(
      child,
      `${path}.${key}`
    );
  }
}


scanForbiddenKeys(
  factPack
);


// ============================================================
// 15. Causal Integrity
// ============================================================

const strongCausalPatterns = [

  '때문에',
  '때문이다',
  '때문입니다',

  '로 인한',
  '으로 인한',

  '로 인해',
  '으로 인해',

  '원인이다',
  '원인입니다',
  '원인은',
  '원인으로',

  '유발한다',
  '유발합니다',
  '유발할 수',

  '초래한다',
  '초래합니다',

  '발생시킨다',
  '발생시킵니다',

  'because',
  'because of',

  'caused by',
  'cause ',
  'causes',

  'due to',

  'results from',
  'result of',

  'leads to'

];


function containsStrongCausal(
  text
) {

  return strongCausalPatterns
    .some(pattern =>

      containsPattern(
        text,
        pattern
      )

    );
}


const causalChecks = [];


for (
  const fact
  of facts
) {

  const factId =
    cleanText(
      fact.id
    );

  const claim =
    getFactText(
      fact
    );


  if (
    !containsStrongCausal(
      claim
    )
  ) {
    continue;
  }


  const supportQuotes =
    Array.isArray(
      fact.support_quotes
    )
      ? fact.support_quotes
      : [];


  const quoteText =
    supportQuotes
      .map(item =>
        cleanText(
          item?.quote
        )
      )
      .filter(Boolean)
      .join(' ');


  const quoteHasCausal =
    containsStrongCausal(
      quoteText
    );


  const coverageResult =
    coverageMap.get(
      factId
    );


  const unsupportedMeaning =
    Boolean(
      coverageResult &&
      coverageResult
        .unsupported_phrases
        .length > 0
    );


  const supported =
    quoteHasCausal &&
    !unsupportedMeaning;


  causalChecks.push({

    fact_id:
      factId,

    fact_text:
      claim,

    quote_has_causal:
      quoteHasCausal,

    unsupported_phrases:
      coverageResult
        ?.unsupported_phrases ??
        [],

    supported

  });


  if (!supported) {

    addError(
      'causal_integrity',
      `검증되지 않은 인과 Fact 감지: ${factId} - ${claim}`
    );
  }
}


// ============================================================
// 16. Final Status
// ============================================================

let finalStatus =
  sourceStatus;


if (
  validationErrors.length > 0
) {

  finalStatus =
    'FAIL';

} else if (
  validationWarnings.length > 0 &&
  finalStatus === 'PASS'
) {

  finalStatus =
    'WARN';
}


const readyForScript =
  (
    finalStatus === 'PASS' ||
    finalStatus === 'WARN'
  ) &&
  validationErrors.length === 0;


// ============================================================
// 17. Output
// ============================================================

return [
