          failed.support_quote_integrity
            ? 'FAIL'
            : 'PASS',

        claim_quote_coverage:
          failed.claim_quote_coverage
            ? 'FAIL'
            : 'PASS',

        qualifier_preservation:
          failed.qualifier_preservation
            ? 'FAIL'
            : 'PASS',

        advice_boundary:
          failed.advice_boundary
            ? 'FAIL'
            : 'PASS',

        safe_framing:
          failed.safe_framing
            ? 'FAIL'
            : 'PASS',

        role_boundary:
          failed.role_boundary
            ? 'FAIL'
            : 'PASS',

        causal_integrity:
          failed.causal_integrity
            ? 'FAIL'
            : 'PASS',

        warnings:
          validationWarnings,

        errors:
          validationErrors

      },

      support_quote_debug: {
        checks:
          supportQuoteChecks
      },

      coverage_debug: {
        checks:
          coverageChecks
      },

      qualifier_debug: {
        checks:
          qualifierChecks
      },

      advice_debug: {
        checks:
          adviceChecks
      },

      safe_framing_debug: {
        checks:
          safeFramingChecks
      },

      causal_debug: {
        checks:
          causalChecks
      },

      status:
        finalStatus,

      ready_for_script:
        readyForScript,

      model:
        ollamaResponse.model ||
        pipelineConfig.engines?.planner?.model ||
        '',

      run_id:
        pipelineConfig.run_id,

      run_name:
        pipelineConfig.run_name,

      pipeline_version:
        pipelineConfig.pipeline_version

    }
  }
];

