const config =
  $('Pipeline Config').first().json;


const audience =
  typeof config.input?.audience === 'string'
    ? config.input.audience.trim()
    : 'general';


const tone =
  typeof config.input?.tone === 'string'
    ? config.input.tone.trim()
    : 'natural';


const targetDurationSec =
  Number(
    config.runtime?.requested_duration ??
    config.input?.duration
  );


const sceneCount =
  Number(
    config.runtime?.scene_count
  );


if (
  !Number.isFinite(targetDurationSec) ||
  targetDurationSec <= 0
) {
  throw new Error(
    'Script Writer Input v1.2: target duration 오류'
  );
}


if (
  !Number.isInteger(sceneCount) ||
  sceneCount <= 0
) {
  throw new Error(
    'Script Writer Input v1.2: scene_count 오류'
  );
}


// ============================================================
