const model =
  typeof config.engines?.planner?.model === 'string'
    ? config.engines.planner.model.trim()
    : '';


if (!model) {
  throw new Error(
    'Script Writer Input v1.2: Ollama model 정보가 없습니다.'
  );
}


// ============================================================
// 5. Facts
// ============================================================

const facts =
  Array.isArray(factPack.facts)
    ? factPack.facts
    : [];


const scriptFacts =
  facts
    .filter(
      fact =>
        fact &&
        fact.script_use !== 'AVOID'
    )
    .map(
      fact => {

        return {

          id:
            fact.id,

          claim:
            typeof fact.claim === 'string'
              ? fact.claim.trim()
              : '',

          confidence:
            fact.confidence,

          script_use:
            fact.script_use,

          evidence_ids:
            Array.isArray(
              fact.evidence_ids
            )
              ? fact.evidence_ids
              : []

        };

      }
    )
    .filter(
      fact =>
        fact.id &&
        fact.claim
    );


if (
  scriptFacts.length === 0
) {
  throw new Error(
    'Script Writer Input v1.2: 사용할 Fact가 없습니다.'
  );
}


// ============================================================
// 6. Fact IDs
// ============================================================

const allowedFactIds =
  scriptFacts.map(
    fact =>
      fact.id
  );


const qualifyFactIds =
  scriptFacts
    .filter(
      fact =>
        fact.script_use === 'QUALIFY'
    )
    .map(
      fact =>
        fact.id
    );


// ============================================================
// 7. Uncertainty Guidance
// ============================================================

const uncertaintyGuidance =
  Array.isArray(
    factPack.uncertainties
  )
    ? factPack.uncertainties
        .map(
          item =>
            typeof item?.guidance === 'string'
              ? item.guidance.trim()
              : ''
        )
        .filter(Boolean)
    : [];


// ============================================================
// 8. Safe Framing
// ============================================================

const safeFraming =
  Array.isArray(
    factPack.safe_framing
  )
    ? factPack.safe_framing
        .filter(
          item =>
            typeof item === 'string' &&
            item.trim()
        )
        .map(
          item =>
            item.trim()
        )
    : [];


// ============================================================
// 9. Prohibited Claims
// ============================================================

const prohibitedClaims =
  Array.isArray(
    factPack.prohibited_claims
  )
    ? factPack.prohibited_claims
        .filter(
          item =>
            typeof item === 'string' &&
            item.trim()
        )
        .map(
          item =>
            item.trim()
        )
    : [];


// ============================================================
// 10. System Prompt
// ============================================================

const systemPrompt = `
