// ============================================================
// Script Validator v1.6
// AI Video Factory
// ============================================================
// Role
// - Script Writer JSON parsing
// - Fact ID / QUALIFY / Closing validation
// - Role boundary validation
// - Advice detection
// - Duration preflight
// - Strong causal expression detection
// - NEW v1.6:
//   Each causal sentence must be directly supported by
//   a USED + HIGH + ALLOW Fact containing causal evidence.
// ============================================================


// ============================================================
// 1. Input
// ============================================================

const input =
  $input.first()?.json || {};

if (
  !input ||
  typeof input !== 'object'
) {
  throw new Error(
    'Script Validator: Ollama 응답이 없습니다.'
  );
}


if (
  input.done !== true
) {
  throw new Error(
    'Script Validator: Ollama 응답이 완료되지 않았습니다.'
  );
}


const message =
  input.message;

if (
  !message ||
  typeof message !== 'object'
) {
  throw new Error(
    'Script Validator: message 객체가 없습니다.'
  );
}


let raw =
  typeof message.content === 'string'
    ? message.content.trim()
    : '';

if (!raw) {
  throw new Error(
    'Script Validator: message.content가 비어 있습니다.'
  );
}


// ============================================================
// 2. Strip Markdown Fence
// ============================================================

raw =
  raw
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();


// ============================================================
// 3. Parse JSON
// ============================================================

let script;

try {

  script =
    JSON.parse(raw);

} catch (error) {

  throw new Error(
    `Script Validator: JSON 파싱 실패 - ${error.message}`
  );
}


// ============================================================
// 4. Pipeline Config
// ============================================================

const config =
  $('Pipeline Config').first().json;


const requestedDurationSec =
  Number(
    config.runtime?.requested_duration ??
    config.input?.duration
  );


if (
  !Number.isFinite(requestedDurationSec) ||
  requestedDurationSec <= 0
) {
  throw new Error(
    'Script Validator: 목표 영상 길이가 올바르지 않습니다.'
  );
}


// ============================================================
// 5. Fact Pack
// ============================================================

const factPack =
  $('Fact Pack Validator').first().json;


if (
  !factPack ||
  factPack.stage !== 'fact_pack_validated'
) {
  throw new Error(
    'Script Validator: Fact Pack Validator 결과를 찾을 수 없습니다.'
  );
}


const facts =
  Array.isArray(factPack.facts)
    ? factPack.facts
    : [];


const uncertainties =
  Array.isArray(factPack.uncertainties)
    ? factPack.uncertainties
    : [];


const prohibitedClaims =
  Array.isArray(factPack.prohibited_claims)
    ? factPack.prohibited_claims
    : [];


// ============================================================
// 6. Helpers
// ============================================================

function cleanText(value) {

  return String(value || '')
    .replace(/\s+/g, ' ')
    .trim();
}


function normalizeText(value) {

  return cleanText(value)
    .toLowerCase();
}


function uniqueStrings(values) {

  return [
    ...new Set(
      values
        .map(value => cleanText(value))
        .filter(Boolean)
    )
  ];
}


function getFactText(fact) {

  if (
    !fact ||
    typeof fact !== 'object'
  ) {
    return '';
  }

  return cleanText(
    fact.statement ??
    fact.fact ??
    fact.text ??
    fact.claim ??
    fact.description ??
    ''
  );
}


function containsPattern(
  text,
  pattern
) {

  return normalizeText(text)
    .includes(
      normalizeText(pattern)
    );
}


function splitSentences(text) {

  const normalized =
    cleanText(text);

  if (!normalized) {
    return [];
  }

  return normalized
    .split(
      /(?<=[.!?。！？])\s+|\n+/g
    )
    .map(sentence =>
      cleanText(sentence)
    )
    .filter(Boolean);
}


// ============================================================
// 7. Basic Schema Validation
// ============================================================

const warnings = [];
const errors = [];


const scriptVersion =
  cleanText(
    script.script_version
  );


const title =
  cleanText(
    script.title
  );


const hook =
  cleanText(
    script.hook
  );


const narration =
  cleanText(
    script.narration
  );


const closing =
  cleanText(
    script.closing
  );


if (
  scriptVersion !== '1.2'
) {

  errors.push(
    `지원하지 않는 script_version: ${scriptVersion}`
  );
}


if (!hook) {

  errors.push(
    'hook이 비어 있습니다.'
  );
}


if (!narration) {

  errors.push(
    'narration이 비어 있습니다.'
  );
}


if (closing) {

  errors.push(
    'closing은 반드시 빈 문자열이어야 합니다.'
  );
}


// ============================================================
// 8. Fact ID Validation
// ============================================================

const allowedFactIds =
  new Set(
    facts
      .map(fact =>
        cleanText(fact.id)
      )
      .filter(Boolean)
  );


const usedFactIds =
  uniqueStrings(
    Array.isArray(script.used_fact_ids)
      ? script.used_fact_ids
      : []
  );


const qualifiedFactIds =
  uniqueStrings(
    Array.isArray(script.qualified_fact_ids)
      ? script.qualified_fact_ids
      : []
  );


for (
  const factId
  of usedFactIds
) {

  if (
    !allowedFactIds.has(factId)
  ) {

    errors.push(
      `허용되지 않은 Fact ID 참조: ${factId}`
    );
  }
}


for (
  const factId
  of qualifiedFactIds
) {

  if (
    !usedFactIds.includes(factId)
  ) {

    errors.push(
      `qualified_fact_ids의 ${factId}가 used_fact_ids에 없습니다.`
    );
  }
}


// ============================================================
// 9. QUALIFY Tracking
// ============================================================

const requiredQualifiedIds =
  facts
    .filter(fact =>

      cleanText(
        fact.script_use
      ).toUpperCase() ===
      'QUALIFY'

    )
    .map(fact =>
      cleanText(fact.id)
    )
    .filter(Boolean);


for (
  const factId
  of requiredQualifiedIds
) {

  if (
    usedFactIds.includes(factId) &&
    !qualifiedFactIds.includes(factId)
  ) {

    errors.push(
      `QUALIFY Fact ${factId}가 qualified_fact_ids에 없습니다.`
    );
  }
}


// ============================================================
// 10. Forbidden Role Fields
// ============================================================

const forbiddenKeys =
  new Set([
    'scenes',
    'scene',
    'image_prompt',
    'motion_prompt',
    'positive_prompt',
    'negative_prompt',
    'camera',
    'lighting',
    'visual_style',
    'width',
    'height',
    'frames',
    'fps',
    'cfg',
    'steps',
    'sampler'
  ]);


function scanForbiddenKeys(
  value,
  path = 'root'
) {

  if (
    !value ||
    typeof value !== 'object'
  ) {
    return;
  }


  if (
    Array.isArray(value)
  ) {

    value.forEach(
      (child, index) =>

        scanForbiddenKeys(
          child,
          `${path}[${index}]`
        )
    );

    return;
  }


  for (
    const [key, child]
    of Object.entries(value)
  ) {

    if (
      forbiddenKeys.has(key)
    ) {

      errors.push(
        `역할 침범 필드 감지: ${path}.${key}`
      );
    }


    scanForbiddenKeys(
      child,
      `${path}.${key}`
    );
  }
}


scanForbiddenKeys(script);


// ============================================================
// 11. Full Script Text
// ============================================================

const fullScriptText =
  cleanText(
    `${hook} ${narration} ${closing}`
  );


// ============================================================
// 12. Advice Detection
// ============================================================

const advicePatterns = [

  '하세요',
  '해보세요',
  '확인하세요',
  '주의하세요',
  '기억하세요',
  '알아두세요',

  '추천합니다',
  '권장합니다',

  '병원에 가',
  '병원을 방문',
  '수의사와 상담',
  '전문가와 상담'

];


const foundAdvice =
  advicePatterns
    .filter(pattern =>

      containsPattern(
        fullScriptText,
        pattern
      )

    );


if (
  foundAdvice.length > 0
) {

  warnings.push(
    `권고성 표현 감지: ${foundAdvice.join(', ')}`
  );
}


// ============================================================
// 13. Prohibited Claim Detection
// ============================================================

for (
  const claim
  of prohibitedClaims
) {

  const claimText =
    typeof claim === 'string'
      ? cleanText(claim)
      : cleanText(
          claim?.claim ??
          claim?.text ??
          claim?.statement ??
          ''
        );


  if (
    claimText &&
    containsPattern(
      fullScriptText,
      claimText
    )
  ) {

    errors.push(
      `금지 Claim 사용 감지: ${claimText}`
    );
  }
}


// ============================================================
// 14. Causal Integrity v1.6
// ============================================================
//
// Rule:
//
// Script causal sentence
//       ↓
// Must be supported by a USED Fact
//       ↓
// confidence = HIGH
// script_use = ALLOW
//       ↓
// The Fact itself must contain causal language
//       ↓
// Script sentence and Fact must share
// at least 2 meaningful content tokens.
//
// Otherwise FAIL.
// ============================================================


// ------------------------------------------------------------
// 14-1. Strong Causal Expressions
// ------------------------------------------------------------

const strongCausalPatterns = [

  '때문에',
  '때문이다',
  '때문입니다',

  '로 인한',
  '으로 인한',

  '로 인해',
  '으로 인해',

  '원인이다',
  '원인입니다',
  '원인은',
  '원인으로',
  '원인이 되어',
  '원인이 돼',

  '유발한다',
  '유발합니다',
  '유발할 수',

  '초래한다',
  '초래합니다',
  '초래할 수',

  '발생시킨다',
  '발생시킵니다',

  '비롯된다',
  '비롯됩니다',

  '결과이다',
  '결과입니다',

  '그래서',
  '따라서',

  'causes',
  'caused by',
  'because of',
  'due to',
  'results from',
  'leads to'

];


// ------------------------------------------------------------
// 14-2. Weak Relation Expressions
// ------------------------------------------------------------

const weakRelationPatterns = [

  '관련될 수',
  '관련이 있을 수',

  '나타낼 수',
  '나타날 수',

  '의미할 수',

  '가능성이',

  '일 수 있다',
  '일 수 있습니다',

  'may',
  'might',
  'could',

  'associated with',
  'related to'

];


// ------------------------------------------------------------
// 14-3. Korean / English stop words
// ------------------------------------------------------------

const stopWords =
  new Set([

    '고양이',
    '고양이가',
    '고양이는',

    '우다다',
    '행동',
    '현상',

    '그리고',
    '하지만',
    '또한',

    '것',
    '수',
    '있다',
    '있습니다',
    '합니다',
    '됩니다',

    'the',
    'a',
    'an',
    'and',
    'or',
    'is',
    'are',
    'of',
    'to',
    'for',
    'with',
    'from',
    'by',

    'frap',
    'fraps'

  ]);


// ------------------------------------------------------------
// 14-4. Token normalization
// ------------------------------------------------------------

function normalizeToken(token) {

  let value =
    normalizeText(token)
      .replace(
        /[^0-9a-z가-힣]/gi,
        ''
      );


  if (!value) {
    return '';
  }


  // Basic Korean particle stripping.
  // This is intentionally conservative.

  const endings = [

    '으로부터',
    '에게서',

    '으로',
    '에서',
    '에게',

    '이나',
    '거나',

    '은',
    '는',
    '이',
    '가',

    '을',
    '를',

    '에',
    '의',

    '와',
    '과',

    '로'

  ];


  for (
    const ending
    of endings
  ) {

    if (
      value.length >
      ending.length + 1 &&
      value.endsWith(ending)
    ) {

      value =
        value.slice(
          0,
          -ending.length
        );

      break;
    }
  }


  return value;
}


function contentTokens(text) {

  const rawTokens =
    normalizeText(text)
      .replace(
        /[^0-9a-z가-힣]+/gi,
        ' '
      )
      .split(/\s+/)
      .map(normalizeToken)
      .filter(Boolean);


  const filtered =
    rawTokens
      .filter(token =>

        token.length >= 2 &&
        !stopWords.has(token)

      );


  return [
    ...new Set(filtered)
  ];
}


// ------------------------------------------------------------
// 14-5. Fact metadata normalization
// ------------------------------------------------------------

function normalizeConfidence(fact) {

  return cleanText(
    fact?.confidence
  ).toUpperCase();
}


function normalizeScriptUse(fact) {

  return cleanText(
    fact?.script_use
  ).toUpperCase();
}


function containsStrongCausal(text) {

  return strongCausalPatterns
    .some(pattern =>

      containsPattern(
        text,
        pattern
      )

    );
}


function containsWeakRelation(text) {

  return weakRelationPatterns
    .some(pattern =>

      containsPattern(
        text,
        pattern
      )

    );
}


// ------------------------------------------------------------
// 14-6. Extract causal sentences from script
// ------------------------------------------------------------

const scriptSentences =
  splitSentences(
    `${hook} ${narration}`
  );


const causalSentences =
  scriptSentences
    .filter(sentence =>

      containsStrongCausal(
        sentence
      )

    );


// ------------------------------------------------------------
// 14-7. Candidate supporting facts
// ------------------------------------------------------------

const usedFacts =
  facts
    .filter(fact =>

      usedFactIds.includes(
        cleanText(fact.id)
      )

    );


const highAllowFacts =
  usedFacts
    .filter(fact =>

      normalizeConfidence(fact) ===
        'HIGH' &&

      normalizeScriptUse(fact) ===
        'ALLOW'

    );


const highAllowCausalFacts =
  highAllowFacts
    .filter(fact =>

      containsStrongCausal(
        getFactText(fact)
      )

    );


// ------------------------------------------------------------
// 14-8. Sentence ↔ Fact support matching
// ------------------------------------------------------------

const causalChecks = [];


for (
  const sentence
  of causalSentences
) {

  const sentenceTokens =
    contentTokens(
      sentence
    );


  let bestMatch = null;


  for (
    const fact
    of highAllowCausalFacts
  ) {

    const factText =
      getFactText(fact);


    const factTokens =
      contentTokens(
        factText
      );


    const overlaps =
      sentenceTokens
        .filter(token =>
          factTokens.includes(token)
        );


    const uniqueOverlap =
      [
        ...new Set(overlaps)
      ];


    const overlapCount =
      uniqueOverlap.length;


    const denominator =
      Math.max(
        1,
        Math.min(
          sentenceTokens.length,
          factTokens.length
        )
      );


    const overlapRatio =
      overlapCount /
      denominator;


    const match = {

      fact_id:
        cleanText(fact.id),

      confidence:
        normalizeConfidence(fact),

      script_use:
        normalizeScriptUse(fact),

      fact_text:
        factText,

      shared_tokens:
        uniqueOverlap,

      overlap_count:
        overlapCount,

      overlap_ratio:
        Number(
          overlapRatio.toFixed(3)
        )

    };


    if (
      !bestMatch ||
      match.overlap_count >
        bestMatch.overlap_count ||
      (
        match.overlap_count ===
          bestMatch.overlap_count &&
        match.overlap_ratio >
          bestMatch.overlap_ratio
      )
    ) {

      bestMatch =
        match;
    }
  }


  const supported =
    Boolean(
      bestMatch &&
      (
        bestMatch.overlap_count >= 2 ||
        (
          bestMatch.overlap_count >= 1 &&
          bestMatch.overlap_ratio >= 0.5
        )
      )
    );


  causalChecks.push({

    sentence,

    supported,

    best_match:
      bestMatch

  });


  if (!supported) {

    errors.push(
      `검증되지 않은 인과 문장 감지: ${sentence}`
    );
  }
}


// ------------------------------------------------------------
// 14-9. Strength escalation guard
// ------------------------------------------------------------
//
// If a used QUALIFY / MEDIUM Fact only expresses
// possibility or association, a strong causal statement
// may not replace it.
// ------------------------------------------------------------

const weakQualifiedFacts =
  usedFacts
    .filter(fact => {

      const confidence =
        normalizeConfidence(fact);

      const scriptUse =
        normalizeScriptUse(fact);

      const text =
        getFactText(fact);


      return (

        (
          confidence === 'MEDIUM' ||
          scriptUse === 'QUALIFY'
        ) &&

        containsWeakRelation(text)

      );
    });


if (
  causalSentences.length > 0 &&
  weakQualifiedFacts.length > 0
) {

  for (
    const fact
    of weakQualifiedFacts
  ) {

    const factTokens =
      contentTokens(
        getFactText(fact)
      );


    for (
      const sentence
      of causalSentences
    ) {

      const sentenceTokens =
        contentTokens(
          sentence
        );


      const overlapCount =
        sentenceTokens
          .filter(token =>
            factTokens.includes(token)
          )
          .length;


      if (
        overlapCount >= 2
      ) {

        errors.push(
          `QUALIFY Fact ${cleanText(fact.id)}의 가능성/관련성이 직접 인과관계로 강화되었습니다.`
        );
      }
    }
  }
}


// ============================================================
// 15. Duration Preflight
// ============================================================
//
// Korean informational narration baseline.
// Final timing is handled later by TTS + Whisper.
// ============================================================

const charsPerSecond =
  4.1;


const speechText =
  cleanText(
    `${hook} ${narration}`
  )
    .replace(
      /[\s.,!?'"“”‘’()[\]{}:;·…/\\|_-]/g,
      ''
    );


const characterCount =
  cleanText(
    `${hook} ${narration} ${closing}`
  ).length;


const wordCount =
  cleanText(
    `${hook} ${narration}`
  )
    .split(/\s+/)
    .filter(Boolean)
    .length;


const speechCharacterCount =
  speechText.length;


const estimatedDurationSec =
  Number(
    (
      speechCharacterCount /
      charsPerSecond
    ).toFixed(1)
  );


const durationRatio =
  Number(
    (
      estimatedDurationSec /
      requestedDurationSec
    ).toFixed(3)
  );


let durationPreflight =
  'PASS';


if (
  durationRatio < 0.5
) {

  durationPreflight =
    'FAIL';


  errors.push(
    `대본 길이 심각 부족: 예상 ${estimatedDurationSec}초 / 목표 ${requestedDurationSec}초`
  );

} else if (
  durationRatio < 0.7
) {

  durationPreflight =
    'WARN';


  warnings.push(
    `대본 길이 부족 가능성: 예상 ${estimatedDurationSec}초 / 목표 ${requestedDurationSec}초`
  );
}


// ============================================================
// 16. Error Type Classification
// ============================================================

const causalIntegrityFailed =
  errors.some(error =>

    error.includes(
      '검증되지 않은 인과'
    ) ||

    error.includes(
      '직접 인과관계로 강화'
    )

  );


const roleBoundaryFailed =
  errors.some(error =>

    error.includes(
      '역할 침범'
    )

  );


const factReferenceFailed =
  errors.some(error =>

    error.includes(
      'Fact ID'
    )

  );


const qualifyTrackingFailed =
  errors.some(error =>

    error.includes(
      'qualified_fact_ids'
    ) ||

    error.includes(
      'QUALIFY Fact'
    )

  );


const structureFailed =
  errors.some(error =>

    error.includes(
      'script_version'
    ) ||

    error.includes(
      'hook이'
    ) ||

    error.includes(
      'narration이'
    )

  );


// ============================================================
// 17. Final Routing
// ============================================================

let status =
  'PASS';


let needsEvidenceExpansion =
  false;


let readyForSceneAdapter =
  true;


let nextRoute =
  'scene_adapter';


if (
  causalIntegrityFailed ||
  roleBoundaryFailed ||
  factReferenceFailed ||
  qualifyTrackingFailed ||
  structureFailed ||
  closing
) {

  status =
    'FAIL';

  needsEvidenceExpansion =
    false;

  readyForSceneAdapter =
    false;

  nextRoute =
    'script_review';

} else if (
  durationPreflight === 'FAIL'
) {

  status =
    'FAIL';

  needsEvidenceExpansion =
    true;

  readyForSceneAdapter =
    false;

  nextRoute =
    'evidence_expansion';

} else if (
  errors.length > 0
) {

  status =
    'FAIL';

  needsEvidenceExpansion =
    false;

  readyForSceneAdapter =
    false;

  nextRoute =
    'script_review';

} else if (
  warnings.length > 0
) {

  status =
    'WARN';

  needsEvidenceExpansion =
    false;

  readyForSceneAdapter =
    true;

  nextRoute =
    'scene_adapter';
}


// ============================================================
// 18. Validation Summary
// ============================================================

const validation = {

  structure:
    structureFailed
      ? 'FAIL'
      : 'PASS',

  fact_id_reference:
    factReferenceFailed
      ? 'FAIL'
      : 'PASS',

  qualify_tracking:
    qualifyTrackingFailed
      ? 'FAIL'
      : 'PASS',

  closing:
    closing
      ? 'FAIL'
      : 'PASS',

  role_boundary:
    roleBoundaryFailed
      ? 'FAIL'
      : 'PASS',

  advice_detection:
    foundAdvice.length > 0
      ? 'WARN'
      : 'PASS',

  causal_integrity:
    causalIntegrityFailed
      ? 'FAIL'
      : 'PASS',

  duration_preflight:
    durationPreflight,

  warnings,

  errors

};


// ============================================================
// 19. Output
// ============================================================

return [
  {
    json: {

      stage:
        'script_validated',

      validator_version:
        '1.6',

      script_version:
        scriptVersion,

      title,

      hook,

      narration,

      closing,

      used_fact_ids:
        usedFactIds,

      qualified_fact_ids:
        qualifiedFactIds,

      validation,

      causal_debug: {

        causal_sentence_count:
          causalSentences.length,

        causal_sentences:
          causalSentences,

        eligible_high_allow_causal_fact_ids:
          highAllowCausalFacts
            .map(fact =>
              cleanText(fact.id)
            ),

        checks:
          causalChecks

      },

      metrics: {

        character_count:
          characterCount,

        word_count:
          wordCount,

        speech_character_count:
          speechCharacterCount,

        chars_per_second_assumption:
          charsPerSecond,

        estimated_duration_sec:
          estimatedDurationSec,

        requested_duration_sec:
          requestedDurationSec,

        duration_ratio:
          durationRatio

      },

      status,

      needs_evidence_expansion:
        needsEvidenceExpansion,

      ready_for_scene_adapter:
        readyForSceneAdapter,

      next_route:
        nextRoute,

      model:
        config.engines?.planner?.model || '',

      run_id:
        config.run_id,

      run_name:
        config.run_name,

      pipeline_version:
        config.pipeline_version

    }
  }
];

const input = $input.first()?.json || {};
return [{json:{
  stage:'pipeline_stopped',
  status:'STOPPED',
  reason:'Insufficient or invalid verified script after validation.',
  validation:input.validation || {},
  metrics:input.metrics || {},
  run_id:input.run_id || $('Pipeline Config').first().json.run_id,
  pipeline_version:$('Pipeline Config').first().json.pipeline_version
}}];

// ============================================================
// Evidence Expansion Query Builder v1.1
// AI Video Factory
// ============================================================
// Purpose
//
// Script duration shortage
//      ↓
// identify missing evidence dimensions
//      ↓
// build neutral search queries
//
// IMPORTANT
// - This node NEVER creates Facts.
// - This node NEVER assumes causes.
// - It does NOT inherit speculative meaning/note text
//   from Concept Grounding.
// - Maximum one Evidence Expansion round.
// ============================================================


// ============================================================
// 1. Current Script Validator Output
// ============================================================

const scriptValidation =
  $input.first()?.json || {};


if (
  !scriptValidation ||
  typeof scriptValidation !== 'object'
) {
  throw new Error(
    'Evidence Expansion Query Builder: Script Validator 입력이 없습니다.'
  );
}


if (
  scriptValidation.stage !== 'script_validated'
) {
  throw new Error(
    'Evidence Expansion Query Builder: script_validated 입력이 아닙니다.'
  );
}


if (
  scriptValidation.needs_evidence_expansion !== true
) {
  throw new Error(
    'Evidence Expansion Query Builder: Evidence Expansion이 필요한 상태가 아닙니다.'
  );
}


// ============================================================
// 2. Pipeline Config
// ============================================================

const pipelineConfig =
  $('Pipeline Config').first().json;


if (
  !pipelineConfig ||
  typeof pipelineConfig !== 'object'
) {
  throw new Error(
    'Evidence Expansion Query Builder: Pipeline Config를 찾을 수 없습니다.'
  );
}


// ============================================================
// 3. Helpers
// ============================================================

function cleanText(value) {

  return String(value || '')
    .replace(/\s+/g, ' ')
    .trim();
}


function uniqueStrings(values) {

  return [
    ...new Set(
      values
        .map(value =>
          cleanText(value)
        )
        .filter(Boolean)
    )
  ];
}


function getNodeJson(nodeName) {

  try {

    return (
      $(nodeName).first()?.json ||
      {}
    );

  } catch (error) {

    return {};
  }
}


function containsCausalContamination(text) {

  const value =
    cleanText(text)
      .toLowerCase();


  const patterns = [

    '로 인한',
    '으로 인한',

    '로 인해',
    '으로 인해',

    '때문에',

    '원인이다',
    '원인으로',

    '유발',
    '초래',

    '즐거움이나 에너지로',
    '에너지로 인한',

    'because',
    'because of',

    'caused by',
    'due to',

    'results from',
    'leads to'

  ];


  return patterns.some(pattern =>
    value.includes(
      pattern.toLowerCase()
    )
  );
}


// ============================================================
// 4. Upstream Validated Data
// ============================================================

const factPack =
  getNodeJson(
    'Fact Pack Validator'
  );


if (
  factPack.stage !== 'fact_pack_validated'
) {
  throw new Error(
    'Evidence Expansion Query Builder: Fact Pack Validator 결과를 찾을 수 없습니다.'
  );
}


if (
  factPack.ready_for_script !== true
) {
  throw new Error(
    'Evidence Expansion Query Builder: 검증 완료된 Fact Pack이 아닙니다.'
  );
}


const factPackInput =
  getNodeJson(
    'Fact Pack Input'
  );


const grounding =
  getNodeJson(
    'Concept Grounding Validator'
  );


const evidencePack =
  getNodeJson(
    'Evidence Pack Builder'
  );


// ============================================================
// 5. Expansion Count
// ============================================================
//
// Current architecture allows ONLY one expansion round.
// ============================================================

const previousExpansionCount =
  Number(
    scriptValidation.expansion_count ??
    0
  );


if (
  previousExpansionCount >= 1
) {
  throw new Error(
    'Evidence Expansion Query Builder: 최대 Evidence Expansion 횟수(1회)를 초과했습니다.'
  );
}


const expansionCount =
  previousExpansionCount + 1;


// ============================================================
// 6. Topic Metadata
// ============================================================

const topicOriginal =
  cleanText(
    evidencePack.topic_original ??
    factPackInput.topic_original ??
    grounding.topic_original ??
    ''
  );


const topicNormalized =
  cleanText(
    factPack.topic_normalized ??
    evidencePack.topic_normalized ??
    grounding.topic_normalized ??
    ''
  );


const coreIntent =
  cleanText(
    factPack.core_intent ??
    evidencePack.core_intent ??
    grounding.core_intent ??
    ''
  );


const riskDomain =
  cleanText(
    factPack.risk_domain ??
    evidencePack.risk_domain ??
    grounding.risk_domain ??
    'general'
  );


if (!topicNormalized) {
  throw new Error(
    'Evidence Expansion Query Builder: topic_normalized가 없습니다.'
  );
}


// ============================================================
// 7. Sanitize Grounding Metadata
// ============================================================
//
// IMPORTANT:
// Grounding term descriptions are NOT evidence.
//
// If a meaning/note contains causal interpretation,
// do not pass that interpretation into search expansion.
// ============================================================

const rawKeyTerms =
  Array.isArray(
    grounding.key_terms
  )
    ? grounding.key_terms
    : [];


const keyTerms =
  rawKeyTerms
    .map(item => {

      const term =
        cleanText(
          item?.term
        );


      const meaning =
        cleanText(
          item?.meaning
        );


      return {

        term,

        meaning:
          containsCausalContamination(
            meaning
          )
            ? ''
            : meaning

      };

    })
    .filter(item =>
      item.term
    );


const rawAmbiguities =
  Array.isArray(
    grounding.ambiguities
  )
    ? grounding.ambiguities
    : [];


const ambiguities =
  rawAmbiguities
    .map(item => {

      const expression =
        cleanText(
          item?.expression
        );


      const resolvedAs =
        cleanText(
          item?.resolved_as
        );


      const note =
        cleanText(
          item?.note
        );


      return {

        expression,

        resolved_as:
          resolvedAs,

        note:
          containsCausalContamination(
            note
          )
            ? ''
            : note

      };

    })
    .filter(item =>
      item.expression
    );


const exclusions =
  uniqueStrings(
    Array.isArray(
      grounding.exclusions
    )
      ? grounding.exclusions
      : []
  );


// ============================================================
// 8. Existing Validated Facts
// ============================================================

const existingFacts =
  Array.isArray(
    factPack.facts
  )
    ? factPack.facts.map(fact => ({

        id:
          cleanText(
            fact?.id
          ),

        claim:
          cleanText(
            fact?.claim
          ),

        confidence:
          cleanText(
            fact?.confidence
          ),

        script_use:
          cleanText(
            fact?.script_use
          ),

        evidence_ids:
          Array.isArray(
            fact?.evidence_ids
          )
            ? fact.evidence_ids
            : [],

        support_quotes:
          Array.isArray(
            fact?.support_quotes
          )
            ? fact.support_quotes
            : []

      }))
    : [];


// ============================================================
// 9. Original Evidence
// ============================================================

const originalEvidence =
  Array.isArray(
    factPack.evidence
  )
    ? factPack.evidence
    : [];


// ============================================================
// 10. Topic-Type Detection
// ============================================================
//
// Search specialization only.
// This does NOT create factual claims.
// ============================================================

const topicSearchText =
  [
    topicOriginal,
    topicNormalized,
    coreIntent
  ]
    .join(' ')
    .toLowerCase();


const isAnimalTopic =
  /고양이|강아지|반려동물|동물|cat|cats|dog|dogs|pet|pets/.test(
    topicSearchText
  );


const isHealthTopic =
  riskDomain === 'health';


const expertKo =
  isAnimalTopic
    ? '수의학 전문가 자료'
    : isHealthTopic
      ? '의학 전문가 자료'
      : '전문가 신뢰 자료';


const expertEn =
  isAnimalTopic
    ? 'veterinary behavior evidence'
    : isHealthTopic
      ? 'medical evidence review'
      : 'expert evidence reference';


// ============================================================
// 11. Build Neutral Expansion Queries
// ============================================================
//
// Search for MISSING DIMENSIONS.
//
// No conclusion is embedded in the query.
//
// Avoid:
// "X 때문에"
// "X 원인이다"
// "energy causes"
// etc.
//
// Searching "관련 요인" is allowed because
// it asks for evidence rather than asserting a cause.
// ============================================================

const queries = uniqueStrings([

  `${topicNormalized} 행동 특징 지속 시간 패턴 ${expertKo}`,

  `${topicNormalized} 언제 관찰되는지 시간대 상황 빈도 ${expertKo}`,

  `${topicNormalized} 정상적인 행동 평소와 다른 변화 구분 ${expertKo}`,

  `${topicNormalized} 관련 요인 가능한 설명 근거 ${expertKo}`,

  `${topicNormalized} characteristics duration timing patterns ${expertEn}`,

  `${topicNormalized} normal behavior changes warning signs ${expertEn}`

]).slice(
  0,
  6
);


// ============================================================
// 12. Source Policy
// ============================================================

const sourcePolicy = {

  minimum_sources:
    3,

  target_sources:
    6,

  maximum_sources:
    8

};


// ============================================================
// 13. Evidence Rules
// ============================================================

const evidenceRules = {

  require_multiple_sources:
    true,

  prefer_independent_sources:
    true,

  keep_source_url:
    true,

  keep_source_title:
    true,

  keep_snippet:
    true,

  allow_single_source_claim:
    false,

  allow_unverified_causal_claim:
    false,

  preserve_uncertainty:
    true,

  prohibit_fact_generation:
    true,

  prohibit_assumption_in_search_query:
    true,

  do_not_treat_grounding_as_evidence:
    true

};


// ============================================================
// 14. Output
// ============================================================

return [
  {
    json: {

      stage:
        'evidence_expansion_query_ready',

      expansion_version:
        '1.1',

      expansion_count:
        expansionCount,

      topic_original:
        topicOriginal,

      topic_normalized:
        topicNormalized,

      core_intent:
        coreIntent,

      risk_domain:
        riskDomain,

      key_terms:
        keyTerms,

      ambiguities:
        ambiguities,

      exclusions,

      existing_facts:
        existingFacts,

      original_evidence:
        originalEvidence,

      search: {

        queries,

        language:
          'ko',

        safe_search:
          1

      },

      source_policy:
        sourcePolicy,

      evidence_rules:
        evidenceRules,

      reason: {

        trigger:
          'script_duration_shortage',

        requested_duration_sec:
          Number(
            scriptValidation
              ?.metrics
              ?.requested_duration_sec ??
            0
          ),

        estimated_duration_sec:
          Number(
            scriptValidation
              ?.metrics
              ?.estimated_duration_sec ??
            0
          ),

        duration_ratio:
          Number(
            scriptValidation
              ?.metrics
              ?.duration_ratio ??
            0
          )

      },

      run_id:
        pipelineConfig.run_id,

      run_name:
        pipelineConfig.run_name,

      pipeline_version:
        pipelineConfig.pipeline_version

    }
  }
];

const input = $input.first()?.json || {};
if (input.stage !== 'evidence_expansion_query_ready') throw new Error('Evidence Expansion Query Splitter: 입력 stage 오류');
const queries = Array.isArray(input.search?.queries) ? input.search.queries : [];
if (!queries.length || queries.length > 6) throw new Error('Evidence Expansion Query Splitter: query 개수 오류');
const unique = [...new Set(queries.map(q=>String(q||'').replace(/\s+/g,' ').trim()).filter(Boolean))];
return unique.map((query,index)=>({json:{
  stage:'evidence_expansion_query_split', query_index:index+1, query_total:unique.length, query,
  expansion_count:1, topic_original:input.topic_original, topic_normalized:input.topic_normalized,
  core_intent:input.core_intent, risk_domain:input.risk_domain, key_terms:input.key_terms,
  ambiguities:input.ambiguities, exclusions:input.exclusions, original_evidence:input.original_evidence,
  source_policy:input.source_policy, evidence_rules:input.evidence_rules,
  run_id:input.run_id,run_name:input.run_name,pipeline_version:input.pipeline_version
}}));

// ============================================================
// Evidence Expansion Pack Builder v1.2
// AI Video Factory
// ============================================================
// Purpose
// - Merge original Evidence with Expansion SearXNG results
// - Require genuinely NEW strong evidence
// - Prefer Tier A/B novel sources
// - Never force Tier C novel sources just to fill quota
// - Prevent irrelevant results
// - Never generate Facts
// ============================================================


// ============================================================
// 1. Inputs
// ============================================================

const searchItems =
  $input.all();


if (
  !Array.isArray(searchItems) ||
  searchItems.length === 0
) {
  throw new Error(
    'Evidence Expansion Pack Builder: 검색 결과가 없습니다.'
  );
}


const metaItems =
  $('Evidence Expansion Query Splitter').all();


if (
  !Array.isArray(metaItems) ||
  metaItems.length === 0
) {
  throw new Error(
    'Evidence Expansion Pack Builder: Splitter metadata가 없습니다.'
  );
}


const meta =
  metaItems[0].json || {};


const originalEvidence =
  Array.isArray(meta.original_evidence)
    ? meta.original_evidence
    : [];


// ============================================================
// 2. Source Limits
// ============================================================

const minimumSources =
  Math.max(
    2,
    Number(
      meta.source_policy?.minimum_sources ?? 3
    )
  );


const targetSources =
  Math.max(
    minimumSources,
    Number(
      meta.source_policy?.target_sources ?? 6
    )
  );


const maximumSources =
  Math.max(
    targetSources,
    Number(
      meta.source_policy?.maximum_sources ?? 8
    )
  );


const targetNovelStrongSources =
  2;


// ============================================================
// 3. Helpers
// ============================================================

function clean(value) {

  return typeof value === 'string'
    ? value
        .replace(/\s+/g, ' ')
        .trim()
    : '';
}


function domainOf(url) {

  const match =
    clean(url).match(
      /^https?:\/\/([^\/?#]+)/i
    );


  if (
    !match ||
    !match[1]
  ) {
    return '';
  }


  return match[1]
    .toLowerCase()
    .replace(/^www\./, '')
    .split(':')[0];
}


function canonical(url) {

  let value =
    clean(url)
      .split('#')[0];


  value =
    value
      .replace(
        /([?&])utm_[^=]+=[^&]*&?/gi,
        '$1'
      )
      .replace('?&', '?')
      .replace(/[?&]$/, '');


  return value;
}


function uniqueStrings(values) {

  return [
    ...new Set(
      values
        .map(value =>
          clean(value)
        )
        .filter(Boolean)
    )
  ];
}


// ============================================================
// 4. Source Classification
// ============================================================

const highSourcePatterns = [

  /(^|\.)vcahospitals\.com$/,
  /(^|\.)petmd\.com$/,
  /(^|\.)avma\.org$/,
  /(^|\.)aspca\.org$/,
  /(^|\.)cats\.org\.uk$/,
  /(^|\.)bluecross\.org\.uk$/,
  /(^|\.)rvc\.ac\.uk$/,

  /\.edu$/,
  /\.edu\.[a-z]{2}$/,

  /\.ac\.[a-z]{2}$/,

  /\.gov$/,
  /\.gov\.[a-z]{2}$/

];


const mediumSourcePatterns = [

  /(^|\.)hillspet\.com$/,
  /(^|\.)royalcanin\.com$/,
  /(^|\.)purina\.com$/,
  /(^|\.)fitpetmall\.com$/

];


const lowSourcePatterns = [

  /(^|\.)tistory\.com$/,
  /(^|\.)blog\.naver\.com$/,
  /(^|\.)m\.blog\.naver\.com$/,

  /(^|\.)pinterest\./,

  /(^|\.)namu\.wiki$/,

  /(^|\.)brunch\.co\.kr$/,

  /(^|\.)facebook\.com$/,
  /(^|\.)instagram\.com$/,
  /(^|\.)youtube\.com$/,
  /(^|\.)reddit\.com$/

];


function classify(domain) {

  if (
    highSourcePatterns.some(pattern =>
      pattern.test(domain)
    )
  ) {
    return [
      'A',
      100
    ];
  }


  if (
    mediumSourcePatterns.some(pattern =>
      pattern.test(domain)
    )
  ) {
    return [
      'B',
      75
    ];
  }


  if (
    lowSourcePatterns.some(pattern =>
      pattern.test(domain)
    )
  ) {
    return [
      'D',
      10
    ];
  }


  return [
    'C',
    40
  ];
}


// ============================================================
// 5. Topic Relevance
// ============================================================

function isTopicRelevant(
  title,
  snippet
) {

  const text =
    `${clean(title)} ${clean(snippet)}`
      .toLowerCase();


  const anchors = [

    'zoomies',
    'zoomie',

    'frap',
    'frenetic random activity',

    '우다다'

  ];


  return anchors.some(anchor =>
    text.includes(anchor)
  );
}


// ============================================================
// 6. Original URL Set
// ============================================================

const originalUrlSet =
  new Set();


for (
  const evidence
  of originalEvidence
) {

  const url =
    canonical(
      evidence?.url
    );


  if (url) {
    originalUrlSet.add(url);
  }
}


// ============================================================
// 7. Source Map — Original Evidence
// ============================================================

const sourceMap =
  new Map();


for (
  const evidence
  of originalEvidence
) {

  const url =
    canonical(
      evidence?.url
    );


  const domain =
    domainOf(url);


  const title =
    clean(
      evidence?.title
    );


  const snippet =
    clean(
      evidence?.snippet
    );


  if (
    !url ||
    !domain ||
    !title
  ) {
    continue;
  }


  const classified =
    classify(domain);


  const sourceTier =
    clean(
      evidence?.source_tier
    ) ||
    classified[0];


  const baseScore =
    sourceTier === 'A'
      ? 100
      : sourceTier === 'B'
        ? 75
        : sourceTier === 'C'
          ? 40
          : 10;


  sourceMap.set(
    url,
    {

      url,

      domain,

      title,

      snippet,

      published_date:
        evidence?.published_date ?? null,

      source_tier:
        sourceTier,

      base_score:
        baseScore,

      engine_score:
        0,

      query_support:
        Math.max(
          1,
          Number(
            evidence?.query_support ?? 1
          )
        ),

      matched_queries:
        uniqueStrings(
          Array.isArray(
            evidence?.matched_queries
          )
            ? evidence.matched_queries
            : []
        ),

      original:
        true

    }
  );
}


// ============================================================
// 8. Merge Expansion Results
// ============================================================

let rawResultCount = 0;

let rejectedNoUrl = 0;

let rejectedNoTitle = 0;

let rejectedNoDomain = 0;

let rejectedIrrelevant = 0;


for (
  const item
  of searchItems
) {

  const response =
    item?.json || {};


  const query =
    clean(
      response.query
    );


  const results =
    Array.isArray(
      response.results
    )
      ? response.results
      : [];


  for (
    const result
    of results
  ) {

    rawResultCount += 1;


    const url =
      canonical(
        result?.url
      );


    const title =
      clean(
        result?.title
      );


    const snippet =
      clean(
        result?.content
      );


    const domain =
      domainOf(url);


    if (!url) {

      rejectedNoUrl += 1;

      continue;
    }


    if (!title) {

      rejectedNoTitle += 1;

      continue;
    }


    if (!domain) {

      rejectedNoDomain += 1;

      continue;
    }


    const alreadyOriginal =
      originalUrlSet.has(url);


    if (
      !alreadyOriginal &&
      !isTopicRelevant(
        title,
        snippet
      )
    ) {

      rejectedIrrelevant += 1;

      continue;
    }


    const classified =
      classify(domain);


    const sourceTier =
      classified[0];


    const baseScore =
      classified[1];


    if (
      !sourceMap.has(url)
    ) {

      sourceMap.set(
        url,
        {

          url,

          domain,

          title,

          snippet,

          published_date:
            result?.publishedDate ??
            result?.pubdate ??
            null,

          source_tier:
            sourceTier,

          base_score:
            baseScore,

          engine_score:
            Number(
              result?.score
            ) || 0,

          query_support:
            1,

          matched_queries:
            query
              ? [query]
              : [],

          original:
            false

        }
      );

    } else {

      const source =
        sourceMap.get(url);


      source.query_support += 1;


      source.engine_score =
        Math.max(
          source.engine_score,
          Number(
            result?.score
          ) || 0
        );


      if (
        snippet.length >
        source.snippet.length
      ) {

        source.snippet =
          snippet;
      }


      if (
        query &&
        !source.matched_queries.includes(
          query
        )
      ) {

        source.matched_queries.push(
          query
        );
      }


      if (
        !source.published_date
      ) {

        source.published_date =
          result?.publishedDate ??
          result?.pubdate ??
          null;
      }
    }
  }
}


// ============================================================
// 9. Score
// ============================================================

const scoredSources =
  [...sourceMap.values()]
    .map(source => {

      let score =
        source.base_score;


      score +=
        Math.min(
          source.query_support * 7,
          28
        );


      score +=
        Math.min(
          source.engine_score * 5,
          10
        );


      // Small discovery bonus only.
      // It must never overpower source quality.

      if (!source.original) {
        score += 4;
      }


      if (
        !source.snippet ||
        source.snippet.length < 40
      ) {
        score -= 12;
      }


      const combined =
        `${source.title} ${source.snippet}`
          .toLowerCase();


      if (
        combined.includes('veterinary') ||
        combined.includes('medical') ||
        combined.includes('research')
      ) {
        score += 6;
      }


      if (
        combined.includes('zoomies') ||
        combined.includes('frap') ||
        combined.includes('우다다')
      ) {
        score += 5;
      }


      source.evidence_score =
        Number(
          score.toFixed(2)
        );


      return source;
    })
    .filter(source =>
      source.source_tier !== 'D'
    )
    .sort(
      (a, b) =>
        b.evidence_score -
        a.evidence_score
    );


// ============================================================
// 10. Candidate Pools
// ============================================================

const novelStrongSources =
  scoredSources.filter(source =>

    source.original !== true &&

    (
      source.source_tier === 'A' ||
      source.source_tier === 'B'
    )

  );


const novelWeakSources =
  scoredSources.filter(source =>

    source.original !== true &&

    source.source_tier === 'C'

  );


const originalStrongSources =
  scoredSources.filter(source =>

    source.original === true &&

    (
      source.source_tier === 'A' ||
      source.source_tier === 'B'
    )

  );


const originalWeakSources =
  scoredSources.filter(source =>

    source.original === true &&

    source.source_tier === 'C'

  );


// ============================================================
// 11. Selection Helpers
// ============================================================

const selected = [];


const domainCounts =
  new Map();


function alreadySelected(source) {

  return selected.some(item =>
    item.url === source.url
  );
}


function domainCount(domain) {

  return Number(
    domainCounts.get(domain) || 0
  );
}


function addSource(
  source,
  maxPerDomain = 1
) {

  if (
    !source ||
    alreadySelected(source) ||
    selected.length >= maximumSources
  ) {
    return false;
  }


  if (
    domainCount(
      source.domain
    ) >= maxPerDomain
  ) {
    return false;
  }


  selected.push(source);


  domainCounts.set(
    source.domain,
    domainCount(
      source.domain
    ) + 1
  );


  return true;
}


function addPool(
  pool,
  limit,
  maxPerDomain = 1
) {

  let added = 0;


  for (
    const source
    of pool
  ) {

    if (
      added >= limit ||
      selected.length >= maximumSources
    ) {
      break;
    }


    if (
      addSource(
        source,
        maxPerDomain
      )
    ) {

      added += 1;
    }
  }


  return added;
}


// ============================================================
// 12. Selection
// ============================================================
//
// IMPORTANT:
//
// Do NOT add Tier C novel sources
// merely to reach "2 new URLs".
//
// First:
// new Tier A/B
//
// Then:
// existing Tier A/B
//
// Then:
// existing Tier C if needed.
//
// Novel Tier C is intentionally excluded
// from the final Evidence Pack.
// ============================================================


// ------------------------------------------------------------
// 12-1. Novel strong evidence
// ------------------------------------------------------------

addPool(
  novelStrongSources,
  targetNovelStrongSources,
  1
);


// ------------------------------------------------------------
// 12-2. Original strong evidence
// ------------------------------------------------------------

if (
  selected.length <
  targetSources
) {

  addPool(
    originalStrongSources,
    targetSources -
    selected.length,
    1
  );
}


// ------------------------------------------------------------
// 12-3. Original Tier C only if needed
// ------------------------------------------------------------

if (
  selected.length <
  targetSources
) {

  addPool(
    originalWeakSources,
    targetSources -
    selected.length,
    1
  );
}


// ------------------------------------------------------------
// 12-4. Strong-source domain fallback
// ------------------------------------------------------------

if (
  selected.length <
  minimumSources
) {

  addPool(
    [
      ...novelStrongSources,
      ...originalStrongSources
    ],
    minimumSources -
    selected.length,
    2
  );
}


// ============================================================
// 13. Clean Evidence
// ============================================================

const evidence =
  selected.map(
    (source, index) => {

      return {

        id:
          `E${index + 1}`,

        title:
          source.title,

        url:
          source.url,

        domain:
          source.domain,

        snippet:
          source.snippet,

        published_date:
          source.published_date,

        source_tier:
          source.source_tier,

        evidence_score:
          source.evidence_score,

        query_support:
          source.query_support,

        matched_queries:
          uniqueStrings(
            source.matched_queries
          ),

        evidence_origin:
          source.original
            ? 'original'
            : 'expanded_search'

      };

    }
  );


// ============================================================
// 14. Quality Metrics
// ============================================================

const strongSourceCount =
  evidence.filter(item =>

    item.source_tier === 'A' ||
    item.source_tier === 'B'

  ).length;


const selectedNewStrongSourceCount =
  evidence.filter(item =>

    item.evidence_origin ===
      'expanded_search' &&

    (
      item.source_tier === 'A' ||
      item.source_tier === 'B'
    )

  ).length;


const selectedNewSourceCount =
  evidence.filter(item =>

    item.evidence_origin ===
    'expanded_search'

  ).length;


const selectedOriginalSourceCount =
  evidence.length -
  selectedNewSourceCount;


const expansionEffective =
  selectedNewStrongSourceCount > 0;


// ============================================================
// 15. Status
// ============================================================

let status =
  'PASS';


const warnings = [];


if (
  evidence.length <
  minimumSources
) {

  status =
    'FAIL';


  warnings.push(
    `Evidence 부족: ${evidence.length} / 최소 ${minimumSources}`
  );
}


if (
  selectedNewStrongSourceCount === 0
) {

  status =
    'FAIL';


  warnings.push(
    '새로운 Tier A/B Evidence가 없습니다.'
  );
}


if (
  status !== 'FAIL' &&
  selectedNewStrongSourceCount <
  targetNovelStrongSources
) {

  status =
    'WARN';


  warnings.push(
    `새로운 강한 Evidence 목표 미달: ${selectedNewStrongSourceCount} / ${targetNovelStrongSources}`
  );
}


if (
  status !== 'FAIL' &&
  strongSourceCount < 2
) {

  status =
    'WARN';


  warnings.push(
    `전체 강한 Evidence 부족: ${strongSourceCount}`
  );
}


