// ============================================================
// Fact Pack Validator v1.6.2
// AI Video Factory
// ============================================================
// Main Guards
// - Schema / Evidence reference
// - Confidence / script_use
// - Exact support quote integrity
// - Claim ↔ Quote semantic coverage
// - Cross-language critical meaning guard
// - Behavior vs Change preservation
// - Advice blocking
// - Safe framing allowlist
// - Causal integrity
// ============================================================


// ============================================================
// 1. Input
// ============================================================

const ollamaResponse =
  $input.first()?.json || {};

if (
  !ollamaResponse ||
  typeof ollamaResponse !== 'object'
) {
  throw new Error(
    'Fact Pack Validator: Ollama 응답이 없습니다.'
  );
}

if (
  ollamaResponse.done !== true
) {
  throw new Error(
    'Fact Pack Validator: Ollama 응답이 완료되지 않았습니다.'
  );
}

const ollamaMessage =
  ollamaResponse.message;

if (
  !ollamaMessage ||
  typeof ollamaMessage !== 'object'
) {
  throw new Error(
    'Fact Pack Validator: message 객체가 없습니다.'
  );
}

let rawContent =
  typeof ollamaMessage.content === 'string'
    ? ollamaMessage.content.trim()
    : '';

if (!rawContent) {
  throw new Error(
    'Fact Pack Validator: message.content가 비어 있습니다.'
  );
}


// ============================================================
// 2. JSON Parse
// ============================================================

rawContent =
  rawContent
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

let factPack;

try {

  factPack =
    JSON.parse(rawContent);

} catch (error) {

  throw new Error(
    `Fact Pack Validator: JSON 파싱 실패 - ${error.message}`
  );
}


// ============================================================
// 3. Upstream
// ============================================================

const upstreamFactInput =
  $('Fact Pack Input Expanded').first().json;

if (
  !upstreamFactInput ||
  upstreamFactInput.stage !== 'fact_pack_input'
) {
  throw new Error(
    'Fact Pack Validator: Fact Pack Input 결과가 아닙니다.'
  );
}

const pipelineConfig =
  $('Pipeline Config').first().json;

const upstreamEvidence =
  Array.isArray(upstreamFactInput.evidence)
    ? upstreamFactInput.evidence
    : [];


// ============================================================
// 4. Helpers
// ============================================================

function cleanText(value) {

  return String(value || '')
    .replace(/\s+/g, ' ')
    .trim();
}


function normalizeText(value) {

  return cleanText(value)
    .toLowerCase();
}


function containsPattern(text, pattern) {

  return normalizeText(text)
    .includes(
      normalizeText(pattern)
    );
}


function uniqueStrings(values) {

  return [
    ...new Set(
      values
        .map(value => cleanText(value))
        .filter(Boolean)
    )
  ];
}


function getFactText(fact) {

  return cleanText(
    fact?.claim ??
    fact?.statement ??
    fact?.fact ??
    fact?.text ??
    ''
  );
}


function getFactEvidenceIds(fact) {

  const values =
    fact?.evidence_ids ??
    fact?.evidence_refs ??
    fact?.source_ids ??
    [];

  return uniqueStrings(
    Array.isArray(values)
      ? values
      : []
  );
}


function getEvidenceId(evidence) {

  return cleanText(
    evidence?.id ??
    evidence?.evidence_id ??
    evidence?.source_id ??
    ''
  );
}


function getEvidenceSnippet(evidence) {

  return cleanText(
    evidence?.snippet ??
    evidence?.text ??
    evidence?.content ??
    ''
  );
}


function detectLanguage(text) {

  const value =
    cleanText(text);

  const ko =
    value.match(/[가-힣]+/g) || [];

  const en =
    value.match(/[A-Za-z]+/g) || [];

  if (
    ko.length === 0 &&
    en.length === 0
  ) {
    return 'unknown';
  }

  if (
    ko.length > en.length
  ) {
    return 'ko';
  }

  if (
    en.length > ko.length
  ) {
    return 'en';
  }

  return 'mixed';
}


// ============================================================
// 5. Validation State
// ============================================================

const validationErrors = [];
const validationWarnings = [];

const failed = {

  structure: false,

  evidence_reference: false,

  confidence_policy: false,

  support_quote_integrity: false,

  claim_quote_coverage: false,

  qualifier_preservation: false,

  advice_boundary: false,

  safe_framing: false,

  role_boundary: false,

  causal_integrity: false

};


function addError(
  category,
  message
) {

  if (
    Object.prototype.hasOwnProperty.call(
      failed,
      category
    )
  ) {
    failed[category] = true;
  }

  validationErrors.push(
    message
  );
}


// ============================================================
// 6. Top-Level Schema
// ============================================================

const factPackVersion =
  cleanText(
    factPack.fact_pack_version
  );

const topicNormalized =
  cleanText(
    factPack.topic_normalized
  );

const coreIntent =
  cleanText(
    factPack.core_intent
  );

const riskDomain =
  cleanText(
    factPack.risk_domain
  );

const sourceStatus =
  cleanText(
    factPack.status
  ).toUpperCase();


if (
  factPackVersion !== '1.3'
) {

  addError(
    'structure',
    `지원하지 않는 fact_pack_version: ${factPackVersion}`
  );
}


if (!topicNormalized) {

  addError(
    'structure',
    'topic_normalized가 비어 있습니다.'
  );
}


if (!coreIntent) {

  addError(
    'structure',
    'core_intent가 비어 있습니다.'
  );
}


const allowedRiskDomains =
  new Set([
    'general',
    'science',
    'health',
    'finance',
    'legal',
    'safety'
  ]);


if (
  !allowedRiskDomains.has(
    riskDomain
  )
) {

  addError(
    'structure',
    `지원하지 않는 risk_domain: ${riskDomain}`
  );
}


// ============================================================
// 7. Evidence Map
// ============================================================

const evidenceMap =
  new Map();


for (
  const evidence
  of upstreamEvidence
) {

  const evidenceId =
    getEvidenceId(
      evidence
    );

  if (!evidenceId) {
    continue;
  }

  evidenceMap.set(
    evidenceId,
    evidence
  );
}


if (
  evidenceMap.size === 0
) {

  addError(
    'evidence_reference',
    '사용 가능한 upstream Evidence가 없습니다.'
  );
}


// ============================================================
// 8. Facts / Policy
// ============================================================

const facts =
  Array.isArray(factPack.facts)
    ? factPack.facts
    : [];


if (
  facts.length === 0
) {

  addError(
    'structure',
    'facts 배열이 비어 있습니다.'
  );
}


if (
  facts.length > 5
) {

  addError(
    'structure',
    `facts 개수 초과: ${facts.length} / 최대 5`
  );
}


const allowedConfidence =
  new Set([
    'HIGH',
    'MEDIUM',
    'LOW'
  ]);


const allowedScriptUse =
  new Set([
    'ALLOW',
    'QUALIFY',
    'AVOID'
  ]);


const seenFactIds =
  new Set();


for (
  let index = 0;
  index < facts.length;
  index++
) {

  const fact =
    facts[index] || {};

  const factId =
    cleanText(
      fact.id
    );

  const factText =
    getFactText(
      fact
    );

  const confidence =
    cleanText(
      fact.confidence
    ).toUpperCase();

  const scriptUse =
    cleanText(
      fact.script_use
    ).toUpperCase();

  const evidenceIds =
    getFactEvidenceIds(
      fact
    );


  if (!factId) {

    addError(
      'structure',
      `Fact ${index + 1}: id가 없습니다.`
    );

  } else if (
    seenFactIds.has(factId)
  ) {

    addError(
      'structure',
      `중복 Fact ID: ${factId}`
    );

  } else {

    seenFactIds.add(
      factId
    );
  }


  if (!factText) {

    addError(
      'structure',
      `${factId}: claim이 없습니다.`
    );
  }


  if (
    !allowedConfidence.has(
      confidence
    )
  ) {

    addError(
      'confidence_policy',
      `${factId}: 지원하지 않는 confidence: ${confidence}`
    );
  }


  if (
    !allowedScriptUse.has(
      scriptUse
    )
  ) {

    addError(
      'confidence_policy',
      `${factId}: 지원하지 않는 script_use: ${scriptUse}`
    );
  }


  if (
    confidence === 'MEDIUM' &&
    scriptUse === 'ALLOW'
  ) {

    addError(
      'confidence_policy',
      `${factId}: MEDIUM Fact는 ALLOW를 사용할 수 없습니다.`
    );
  }


  if (
    confidence === 'LOW' &&
    scriptUse !== 'AVOID'
  ) {

    addError(
      'confidence_policy',
      `${factId}: LOW Fact는 반드시 AVOID여야 합니다.`
    );
  }


  if (
    evidenceIds.length === 0
  ) {

    addError(
      'evidence_reference',
      `${factId}: evidence_ids가 없습니다.`
    );
  }


  for (
    const evidenceId
    of evidenceIds
  ) {

    if (
      !evidenceMap.has(
        evidenceId
      )
    ) {

      addError(
        'evidence_reference',
        `${factId}: 존재하지 않는 Evidence ID: ${evidenceId}`
      );
    }
  }


  if (
    confidence === 'HIGH' &&
    scriptUse === 'ALLOW' &&
    evidenceIds.length < 2
  ) {

    addError(
      'confidence_policy',
      `${factId}: HIGH + ALLOW는 최소 2개 Evidence가 필요합니다.`
    );
  }
}


// ============================================================
// 9. Exact Support Quote Integrity
// ============================================================

const supportQuoteChecks = [];


for (
  const fact
  of facts
) {

  const factId =
    cleanText(
      fact.id
    );

  const evidenceIds =
    getFactEvidenceIds(
      fact
    );

  const supportQuotes =
    Array.isArray(
      fact.support_quotes
    )
      ? fact.support_quotes
      : [];

  const checks = [];


  if (
    supportQuotes.length === 0
  ) {

    addError(
      'support_quote_integrity',
      `${factId}: support_quotes가 없습니다.`
    );
  }


  for (
    const item
    of supportQuotes
  ) {

    const evidenceId =
      cleanText(
        item?.evidence_id
      );

    const quote =
      cleanText(
        item?.quote
      );

    let valid = true;

    const reasons = [];


    if (
      !evidenceId ||
      !evidenceIds.includes(
        evidenceId
      )
    ) {

      valid = false;

      reasons.push(
        'Fact evidence_ids와 불일치'
      );

      addError(
        'support_quote_integrity',
        `${factId}: support quote Evidence ID 오류: ${evidenceId}`
      );
    }


    const evidence =
      evidenceMap.get(
        evidenceId
      );

    let quoteExists =
      false;


    if (
      evidence &&
      quote
    ) {

      quoteExists =
        normalizeText(
          getEvidenceSnippet(
            evidence
          )
        ).includes(
          normalizeText(
            quote
          )
        );
    }


    if (!quoteExists) {

      valid = false;

      reasons.push(
        'Evidence snippet 원문에 quote 없음'
      );

      addError(
        'support_quote_integrity',
        `${factId}: support quote가 ${evidenceId} 원문에 존재하지 않습니다.`
      );
    }


    checks.push({

      evidence_id:
        evidenceId,

      quote,

      quote_exists:
        quoteExists,

      valid,

      reasons

    });
  }


  supportQuoteChecks.push({

    fact_id:
      factId,

    valid:
      supportQuotes.length > 0 &&
      checks.every(
        check =>
          check.valid
      ),

    checks

  });
}


// ============================================================
// 10. Critical Semantic Coverage
// ============================================================
//
// Cross-language에서는 일반 token overlap을 사용하지 않고
// 의미가 변하기 쉬운 핵심 요소만 결정론적으로 검사.
// ============================================================

const semanticRules = [

  // ----------------------------------------------------------
  // Duration
  // ----------------------------------------------------------

  {
    label:
      '몇 분',

    claim_patterns: [
      '몇 분',
      '몇분'
    ],

    quote_patterns: [
      '몇 분',
      '몇분',
      'few minutes',
      'minutes or less'
    ]
  },


  // ----------------------------------------------------------
  // NEW v1.6.2
  // Sudden onset / beginning
  // ----------------------------------------------------------

  {
    label:
      '갑자기 시작',

    claim_patterns: [
