      '갑작스럽게 시작',
      '갑작스레 시작',
      '갑자기 발생',
      '갑작스럽게 발생',
      '갑자기 나타',
      '갑작스럽게 나타'
    ],

    quote_patterns: [
      '갑자기 시작',
      '갑작스럽게 시작',
      '갑자기 발생',
      '갑작스럽게 발생',
      'sudden start',
      'suddenly starts',
      'suddenly started',
      'begins suddenly',
