  // ----------------------------------------------------------

  {
    label:
      '에너지 소비',

    claim_patterns: [
      '에너지를 소비',
      '에너지 소비',
      '에너지를 소모',
      '에너지 소모',
      '에너지를 발산',
      '에너지 발산',
      '에너지를 해소',
      '에너지 해소'
    ],

    quote_patterns: [
      '에너지를 소비',
      '에너지 소비',
      '에너지를 소모',
      '에너지 소모',
