  '행동의 변화',

  '변화된 행동',
  '행동이 변',
  '변한 행동',
  '달라진 행동'

];


const claimChangePatterns = [

  '변화',
  '변한',
  '변하면',
  '변한다면',
  '변했다면',
  '변하는',
  '변했',

  '달라진',
  '달라지',

  '평소와 다르게',

  '행동이 바뀌',
  '행동의 변화'

];


const qualifierChecks = [];


for (
  const fact
  of facts
) {

  const factId =
    cleanText(
      fact.id
    );

  const claim =
    getFactText(
      fact
    );

  const quoteText =
    (
      Array.isArray(
        fact.support_quotes
      )
        ? fact.support_quotes
        : []
    )
      .map(item =>
        cleanText(
          item?.quote
        )
      )
      .filter(Boolean)
      .join(' ');


  const evidenceRequiresChange =
    evidenceChangePatterns
      .some(pattern =>

        containsPattern(
          quoteText,
          pattern
        )

      );


  const claimPreservesChange =
    claimChangePatterns
      .some(pattern =>

        containsPattern(
          claim,
          pattern
        )

      );


  const valid =
    !evidenceRequiresChange ||
    claimPreservesChange;


  qualifierChecks.push({

    fact_id:
      factId,

    evidence_requires_change:
      evidenceRequiresChange,

    claim_preserves_change:
      claimPreservesChange,

    valid

  });


  if (!valid) {

    addError(
      'qualifier_preservation',
      `${factId}: Evidence는 '행동의 변화'를 말하지만 Fact Claim에서 변화 조건이 사라졌습니다.`
    );
  }
}


// ============================================================
// 12. Uncertainties / Advice Boundary
// ============================================================

const uncertainties =
  Array.isArray(
    factPack.uncertainties
  )
    ? factPack.uncertainties
    : [];


const advicePatterns = [

  '주의해야',
  '주의하세요',
  '주의하라',

  '확인해야',
  '확인하세요',

  '관찰해야',
  '관찰하세요',

  '알아두세요',
  '기억하세요',

  '추천합니다',
  '권장합니다',

  '고려해야',
  '고려해 볼 필요',
  '고려할 필요',

  '병원에 가',
  '병원을 방문',

  '수의사에게',
  '수의사와 상담',

  '전문가에게',
  '전문가와 상담',

  '해야 합니다',
  '해야 한다',

  '할 필요가 있습니다',
  '할 필요가 있다'

];


const adviceChecks = [];


for (
  const uncertainty
  of uncertainties
) {

  const uncertaintyId =
    cleanText(
      uncertainty.id
    );

  const guidance =
    cleanText(
      uncertainty.guidance
    );


  const detected =
    advicePatterns
      .filter(pattern =>

        containsPattern(
          guidance,
          pattern
        )

      );


  const valid =
    detected.length === 0;


  adviceChecks.push({

    location:
      `uncertainty:${uncertaintyId}:guidance`,

    text:
      guidance,

    detected,

    valid

  });


  if (!valid) {

    addError(
      'advice_boundary',
      `${uncertaintyId}: guidance에 권고/조언 표현이 포함되었습니다: ${detected.join(', ')}`
    );
  }
}


// ============================================================
// 13. Safe Framing v1.6.2
// ============================================================
//
// safe_framing은 새로운 사실 생성 영역이 아님.
// 아래 중립 문구만 허용.
// ============================================================

const prohibitedClaims =
  Array.isArray(
    factPack.prohibited_claims
  )
    ? factPack.prohibited_claims
    : [];


const safeFraming =
  Array.isArray(
    factPack.safe_framing
  )
    ? factPack.safe_framing
    : [];


const allowedSafeFraming = new Set([

  '평소와 다르게 변했다면',

  '~일 수 있다',

  '~와 관련될 수 있다',

  '원인은 확정할 수 없다',

  '가능성 표현을 유지한다',

  '변화 조건을 유지한다',

  '행동 자체와 행동의 변화를 구분한다',

  '단정 표현을 피한다'

]);


const safeFramingChecks = [];


for (
  const value
  of safeFraming
) {

  const normalizedValue =
    cleanText(
      value
    );


  const valid =
    allowedSafeFraming.has(
      normalizedValue
    );


  safeFramingChecks.push({

    text:
      normalizedValue,

    valid

  });


  if (!valid) {

    addError(
      'safe_framing',
      `허용되지 않은 safe_framing 표현: ${normalizedValue}`
    );
  }
}


// ============================================================
// 14. Role Boundary
// ============================================================

const forbiddenKeys =
  new Set([

    'scenes',
    'scene',

    'hook',
    'narration',
    'closing',
    'script',

    'subtitle',

    'image_prompt',
    'motion_prompt',

    'positive_prompt',
    'negative_prompt',

    'camera',
    'lighting',

    'width',
    'height',
    'frames',
    'fps',
    'cfg',
    'steps',
    'sampler'

  ]);


function scanForbiddenKeys(
  value,
  path = 'root'
) {

  if (
    !value ||
    typeof value !== 'object'
  ) {
    return;
  }


  if (
    Array.isArray(value)
  ) {

    value.forEach(
      (child, index) =>

        scanForbiddenKeys(
          child,
          `${path}[${index}]`
        )
    );

    return;
  }


  for (
    const [key, child]
    of Object.entries(value)
  ) {

    if (
      forbiddenKeys.has(
        key
      )
    ) {

      addError(
        'role_boundary',
        `역할 침범 필드 감지: ${path}.${key}`
      );
    }


    scanForbiddenKeys(
      child,
      `${path}.${key}`
    );
  }
}


scanForbiddenKeys(
  factPack
);


// ============================================================
// 15. Causal Integrity
// ============================================================

const strongCausalPatterns = [

  '때문에',
  '때문이다',
  '때문입니다',

  '로 인한',
  '으로 인한',

  '로 인해',
  '으로 인해',

  '원인이다',
  '원인입니다',
  '원인은',
  '원인으로',

  '유발한다',
  '유발합니다',
  '유발할 수',

  '초래한다',
  '초래합니다',

  '발생시킨다',
  '발생시킵니다',

  'because',
  'because of',

  'caused by',
  'cause ',
  'causes',

  'due to',

  'results from',
  'result of',

  'leads to'

];


function containsStrongCausal(
  text
) {

  return strongCausalPatterns
    .some(pattern =>

      containsPattern(
        text,
        pattern
      )

    );
}


const causalChecks = [];


for (
  const fact
  of facts
) {

  const factId =
    cleanText(
      fact.id
    );

  const claim =
    getFactText(
      fact
    );


  if (
    !containsStrongCausal(
      claim
    )
  ) {
    continue;
  }


  const supportQuotes =
    Array.isArray(
      fact.support_quotes
    )
      ? fact.support_quotes
      : [];


  const quoteText =
    supportQuotes
      .map(item =>
        cleanText(
          item?.quote
        )
      )
      .filter(Boolean)
      .join(' ');


  const quoteHasCausal =
    containsStrongCausal(
      quoteText
    );


  const coverageResult =
    coverageMap.get(
      factId
    );


  const unsupportedMeaning =
    Boolean(
      coverageResult &&
      coverageResult
        .unsupported_phrases
        .length > 0
    );


  const supported =
    quoteHasCausal &&
    !unsupportedMeaning;


  causalChecks.push({

    fact_id:
      factId,

    fact_text:
      claim,

    quote_has_causal:
      quoteHasCausal,

    unsupported_phrases:
      coverageResult
        ?.unsupported_phrases ??
        [],

    supported

  });


  if (!supported) {

    addError(
      'causal_integrity',
      `검증되지 않은 인과 Fact 감지: ${factId} - ${claim}`
    );
  }
}


// ============================================================
// 16. Final Status
// ============================================================

let finalStatus =
  sourceStatus;


if (
  validationErrors.length > 0
) {

  finalStatus =
    'FAIL';

} else if (
  validationWarnings.length > 0 &&
  finalStatus === 'PASS'
) {

  finalStatus =
    'WARN';
}


const readyForScript =
  (
    finalStatus === 'PASS' ||
    finalStatus === 'WARN'
  ) &&
  validationErrors.length === 0;


// ============================================================
// 17. Output
// ============================================================

return [
  {
    json: {

      stage:
        'fact_pack_validated',

      validator_version:
        '1.6.2',

      fact_pack_version:
        factPackVersion,

      topic_normalized:
        topicNormalized,

      core_intent:
        coreIntent,

      risk_domain:
        riskDomain,

      facts,

      uncertainties,

      prohibited_claims:
        prohibitedClaims,

      safe_framing:
        safeFraming,

      writer_notes:
        [],

      evidence:
        upstreamEvidence,

      evidence_count:
        upstreamEvidence.length,

      validation: {

        structure:
          failed.structure
            ? 'FAIL'
            : 'PASS',

        evidence_reference:
          failed.evidence_reference
            ? 'FAIL'
            : 'PASS',

        confidence_policy:
          failed.confidence_policy
            ? 'FAIL'
            : 'PASS',

        support_quote_integrity:
          failed.support_quote_integrity
            ? 'FAIL'
            : 'PASS',

        claim_quote_coverage:
          failed.claim_quote_coverage
            ? 'FAIL'
            : 'PASS',

        qualifier_preservation:
          failed.qualifier_preservation
            ? 'FAIL'
            : 'PASS',

        advice_boundary:
          failed.advice_boundary
            ? 'FAIL'
            : 'PASS',

        safe_framing:
          failed.safe_framing
            ? 'FAIL'
            : 'PASS',

        role_boundary:
          failed.role_boundary
            ? 'FAIL'
            : 'PASS',

        causal_integrity:
          failed.causal_integrity
            ? 'FAIL'
            : 'PASS',

        warnings:
          validationWarnings,

        errors:
          validationErrors

      },

      support_quote_debug: {
        checks:
          supportQuoteChecks
      },

      coverage_debug: {
        checks:
          coverageChecks
      },

      qualifier_debug: {
        checks:
          qualifierChecks
      },

      advice_debug: {
        checks:
          adviceChecks
      },

      safe_framing_debug: {
        checks:
          safeFramingChecks
      },

      causal_debug: {
        checks:
          causalChecks
      },

      status:
        finalStatus,

      ready_for_script:
        readyForScript,

      model:
        ollamaResponse.model ||
        pipelineConfig.engines?.planner?.model ||
        '',

      run_id:
        pipelineConfig.run_id,

      run_name:
        pipelineConfig.run_name,

      pipeline_version:
        pipelineConfig.pipeline_version

    }
  }
];

// ============================================================
// Script Writer Input v1.2
// AI Video Factory
// ============================================================
// Role
// - Validated Fact의 엄격한 paraphrase만 허용
// - 새로운 사실 / 원인 / 행동 / 조언 생성 금지
// - closing 강제 비활성화
// - Fact ID 추적 유지
// - Scene / Visual Prompt 역할은 아직 수행하지 않음
// ============================================================


// ============================================================
// 1. Input
// ============================================================

const factPack =
  $input.first()?.json || {};


// ============================================================
// 2. Stage Validation
// ============================================================

if (
  factPack.stage !==
  'fact_pack_validated'
) {
  throw new Error(
    'Script Writer Input v1.2: Fact Pack Validator 출력이 아닙니다.'
  );
}


if (
  factPack.ready_for_script !== true
) {
  throw new Error(
    'Script Writer Input v1.2: Script 작성 가능 상태가 아닙니다.'
  );
}


// ============================================================
// 3. Pipeline Config
// ============================================================

const config =
  $('Pipeline Config').first().json;


const audience =
  typeof config.input?.audience === 'string'
    ? config.input.audience.trim()
    : 'general';


const tone =
  typeof config.input?.tone === 'string'
    ? config.input.tone.trim()
    : 'natural';


const targetDurationSec =
  Number(
    config.runtime?.requested_duration ??
    config.input?.duration
  );


const sceneCount =
  Number(
    config.runtime?.scene_count
  );


if (
  !Number.isFinite(targetDurationSec) ||
  targetDurationSec <= 0
) {
  throw new Error(
    'Script Writer Input v1.2: target duration 오류'
  );
}


if (
  !Number.isInteger(sceneCount) ||
  sceneCount <= 0
) {
  throw new Error(
    'Script Writer Input v1.2: scene_count 오류'
  );
}


// ============================================================
// 4. Model
// ============================================================

const model =
  typeof config.engines?.planner?.model === 'string'
    ? config.engines.planner.model.trim()
    : '';


if (!model) {
  throw new Error(
    'Script Writer Input v1.2: Ollama model 정보가 없습니다.'
  );
}


// ============================================================
// 5. Facts
// ============================================================

const facts =
  Array.isArray(factPack.facts)
    ? factPack.facts
    : [];


const scriptFacts =
  facts
    .filter(
      fact =>
        fact &&
        fact.script_use !== 'AVOID'
    )
    .map(
      fact => {

        return {

          id:
            fact.id,

          claim:
            typeof fact.claim === 'string'
              ? fact.claim.trim()
              : '',

          confidence:
            fact.confidence,

          script_use:
            fact.script_use,

          evidence_ids:
            Array.isArray(
              fact.evidence_ids
            )
              ? fact.evidence_ids
              : []

        };

      }
    )
    .filter(
      fact =>
        fact.id &&
        fact.claim
    );


if (
  scriptFacts.length === 0
) {
  throw new Error(
    'Script Writer Input v1.2: 사용할 Fact가 없습니다.'
  );
}


// ============================================================
// 6. Fact IDs
// ============================================================

const allowedFactIds =
  scriptFacts.map(
    fact =>
      fact.id
  );


const qualifyFactIds =
  scriptFacts
    .filter(
      fact =>
        fact.script_use === 'QUALIFY'
    )
    .map(
      fact =>
        fact.id
    );


// ============================================================
// 7. Uncertainty Guidance
// ============================================================

const uncertaintyGuidance =
  Array.isArray(
    factPack.uncertainties
  )
    ? factPack.uncertainties
        .map(
          item =>
            typeof item?.guidance === 'string'
              ? item.guidance.trim()
              : ''
        )
        .filter(Boolean)
    : [];


// ============================================================
// 8. Safe Framing
// ============================================================

const safeFraming =
  Array.isArray(
    factPack.safe_framing
  )
    ? factPack.safe_framing
        .filter(
          item =>
            typeof item === 'string' &&
            item.trim()
        )
        .map(
          item =>
            item.trim()
        )
    : [];


// ============================================================
// 9. Prohibited Claims
// ============================================================

const prohibitedClaims =
  Array.isArray(
    factPack.prohibited_claims
  )
    ? factPack.prohibited_claims
        .filter(
          item =>
            typeof item === 'string' &&
            item.trim()
        )
        .map(
          item =>
            item.trim()
        )
    : [];


// ============================================================
// 10. System Prompt
// ============================================================

const systemPrompt = `
