      audience,

      tone,

      target_duration_sec:
        targetDurationSec,

      runtime_scene_count_reference:
        sceneCount,

      model,

      ollama_request:
        ollamaRequest,

      run_id:
        config.run_id,

      run_name:
        config.run_name,

      pipeline_version:
        config.pipeline_version

    }
  }
];

// ============================================================
// Script Validator Expanded v1.6
// AI Video Factory
// ============================================================
// Role
// - Script Writer JSON parsing
// - Fact ID / QUALIFY / Closing validation
// - Role boundary validation
// - Advice detection
// - Duration preflight
// - Strong causal expression detection
// - Causal sentence ↔ validated Fact support check
//
// IMPORTANT
// - This node runs AFTER Evidence Expansion.
// - Evidence Expansion is allowed only once.
// - If duration is still insufficient here:
//     needs_evidence_expansion = false
//     ready_for_scene_adapter = false
//     next_route = "stop"
// ============================================================


// ============================================================
// 1. Input
// ============================================================

const input =
  $input.first()?.json || {};

if (
  !input ||
  typeof input !== 'object'
) {
  throw new Error(
    'Script Validator: Ollama 응답이 없습니다.'
  );
}

if (
  input.done !== true
) {
  throw new Error(
    'Script Validator: Ollama 응답이 완료되지 않았습니다.'
  );
}

const message =
  input.message;

if (
  !message ||
  typeof message !== 'object'
) {
  throw new Error(
    'Script Validator: message 객체가 없습니다.'
  );
}

let raw =
  typeof message.content === 'string'
    ? message.content.trim()
    : '';

if (!raw) {
  throw new Error(
    'Script Validator: message.content가 비어 있습니다.'
  );
}


// ============================================================
// 2. Strip Markdown Fence
// ============================================================

raw =
  raw
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();


// ============================================================
// 3. Parse JSON
// ============================================================

let script;

try {

  script =
    JSON.parse(raw);

} catch (error) {

  throw new Error(
    `Script Validator: JSON 파싱 실패 - ${error.message}`
  );
}


// ============================================================
// 4. Pipeline Config
// ============================================================

const config =
  $('Pipeline Config').first().json;

const requestedDurationSec =
  Number(
    config.runtime?.requested_duration ??
    config.input?.duration
  );

if (
  !Number.isFinite(requestedDurationSec) ||
  requestedDurationSec <= 0
) {
  throw new Error(
    'Script Validator: 목표 영상 길이가 올바르지 않습니다.'
  );
}


// ============================================================
// 5. Expanded Fact Pack
// ============================================================

const factPack =
  $('Fact Pack Validator Expanded').first().json;

if (
  !factPack ||
  factPack.stage !== 'fact_pack_validated'
) {
  throw new Error(
    'Script Validator: Fact Pack Validator Expanded 결과를 찾을 수 없습니다.'
  );
}

const facts =
  Array.isArray(factPack.facts)
    ? factPack.facts
    : [];

const uncertainties =
  Array.isArray(factPack.uncertainties)
    ? factPack.uncertainties
    : [];

const prohibitedClaims =
  Array.isArray(factPack.prohibited_claims)
    ? factPack.prohibited_claims
    : [];


// ============================================================
// 6. Helpers
// ============================================================

function cleanText(value) {

  return String(value || '')
    .replace(/\s+/g, ' ')
    .trim();
}


function normalizeText(value) {

  return cleanText(value)
    .toLowerCase();
}


function uniqueStrings(values) {

  return [
    ...new Set(
      values
        .map(value =>
          cleanText(value)
        )
        .filter(Boolean)
    )
  ];
}


function getFactText(fact) {

  if (
    !fact ||
    typeof fact !== 'object'
  ) {
    return '';
  }

  return cleanText(
    fact.statement ??
    fact.fact ??
    fact.text ??
    fact.claim ??
    fact.description ??
    ''
  );
}


function containsPattern(
  text,
  pattern
) {

  return normalizeText(text)
    .includes(
      normalizeText(pattern)
    );
}


function splitSentences(text) {

  const normalized =
    cleanText(text);

  if (!normalized) {
    return [];
  }

  return normalized
    .split(
      /(?<=[.!?。！？])\s+|\n+/g
    )
    .map(sentence =>
      cleanText(sentence)
    )
    .filter(Boolean);
}


// ============================================================
// 7. Basic Schema Validation
// ============================================================

const warnings = [];
const errors = [];

const scriptVersion =
  cleanText(
    script.script_version
  );

const title =
  cleanText(
    script.title
  );

const hook =
  cleanText(
    script.hook
  );

const narration =
  cleanText(
    script.narration
  );

const closing =
  cleanText(
    script.closing
  );

if (
  scriptVersion !== '1.2'
) {

  errors.push(
    `지원하지 않는 script_version: ${scriptVersion}`
  );
}

if (!hook) {

  errors.push(
    'hook이 비어 있습니다.'
  );
}

if (!narration) {

  errors.push(
    'narration이 비어 있습니다.'
  );
}

if (closing) {

  errors.push(
    'closing은 반드시 빈 문자열이어야 합니다.'
  );
}


// ============================================================
// 8. Fact ID Validation
// ============================================================

const allowedFactIds =
  new Set(
    facts
      .map(fact =>
        cleanText(fact.id)
      )
      .filter(Boolean)
  );

const usedFactIds =
  uniqueStrings(
    Array.isArray(script.used_fact_ids)
      ? script.used_fact_ids
      : []
  );

const qualifiedFactIds =
  uniqueStrings(
    Array.isArray(script.qualified_fact_ids)
      ? script.qualified_fact_ids
      : []
  );

for (
  const factId
  of usedFactIds
) {

  if (
    !allowedFactIds.has(factId)
  ) {

    errors.push(
      `허용되지 않은 Fact ID 참조: ${factId}`
    );
  }
}

for (
  const factId
  of qualifiedFactIds
) {

  if (
    !usedFactIds.includes(factId)
  ) {

    errors.push(
      `qualified_fact_ids의 ${factId}가 used_fact_ids에 없습니다.`
    );
  }
}


// ============================================================
// 9. QUALIFY Tracking
// ============================================================

const requiredQualifiedIds =
  facts
    .filter(fact =>

      cleanText(
        fact.script_use
      ).toUpperCase() ===
      'QUALIFY'

    )
    .map(fact =>
      cleanText(fact.id)
    )
    .filter(Boolean);

for (
  const factId
  of requiredQualifiedIds
) {

  if (
    usedFactIds.includes(factId) &&
    !qualifiedFactIds.includes(factId)
  ) {

    errors.push(
      `QUALIFY Fact ${factId}가 qualified_fact_ids에 없습니다.`
    );
  }
}


// ============================================================
// 10. Forbidden Role Fields
// ============================================================

const forbiddenKeys =
  new Set([
    'scenes',
    'scene',
    'image_prompt',
    'motion_prompt',
    'positive_prompt',
    'negative_prompt',
    'camera',
    'lighting',
    'visual_style',
    'width',
    'height',
    'frames',
    'fps',
    'cfg',
    'steps',
    'sampler'
  ]);

function scanForbiddenKeys(
  value,
  path = 'root'
) {

  if (
    !value ||
    typeof value !== 'object'
  ) {
    return;
  }

  if (
    Array.isArray(value)
  ) {

    value.forEach(
      (child, index) =>

        scanForbiddenKeys(
          child,
          `${path}[${index}]`
        )
    );

    return;
  }

  for (
    const [key, child]
    of Object.entries(value)
  ) {

    if (
      forbiddenKeys.has(key)
    ) {

      errors.push(
        `역할 침범 필드 감지: ${path}.${key}`
      );
    }

    scanForbiddenKeys(
      child,
      `${path}.${key}`
    );
  }
}

scanForbiddenKeys(script);


// ============================================================
// 11. Full Script Text
// ============================================================

const fullScriptText =
  cleanText(
    `${hook} ${narration} ${closing}`
  );


// ============================================================
// 12. Advice Detection
// ============================================================

const advicePatterns = [

  '하세요',
  '해보세요',
  '확인하세요',
  '주의하세요',
  '기억하세요',
  '알아두세요',

  '추천합니다',
  '권장합니다',

  '병원에 가',
  '병원을 방문',
  '수의사와 상담',
  '전문가와 상담'

];

const foundAdvice =
  advicePatterns
    .filter(pattern =>

      containsPattern(
        fullScriptText,
        pattern
      )

    );

if (
  foundAdvice.length > 0
) {

  warnings.push(
    `권고성 표현 감지: ${foundAdvice.join(', ')}`
  );
}


// ============================================================
// 13. Prohibited Claim Detection
// ============================================================

for (
  const claim
  of prohibitedClaims
) {

  const claimText =
    typeof claim === 'string'
      ? cleanText(claim)
      : cleanText(
          claim?.claim ??
          claim?.text ??
          claim?.statement ??
          ''
        );

  if (
    claimText &&
    containsPattern(
      fullScriptText,
      claimText
    )
  ) {

    errors.push(
      `금지 Claim 사용 감지: ${claimText}`
    );
  }
}


// ============================================================
// 14. Causal Integrity v1.6
// ============================================================

// ------------------------------------------------------------
// 14-1. Strong Causal Expressions
// ------------------------------------------------------------

const strongCausalPatterns = [

  '때문에',
  '때문이다',
  '때문입니다',

  '로 인한',
  '으로 인한',

  '로 인해',
  '으로 인해',

  '원인이다',
  '원인입니다',
  '원인은',
  '원인으로',
  '원인이 되어',
  '원인이 돼',

  '유발한다',
  '유발합니다',
  '유발할 수',

  '초래한다',
  '초래합니다',
  '초래할 수',

  '발생시킨다',
  '발생시킵니다',

  '비롯된다',
  '비롯됩니다',

  '결과이다',
  '결과입니다',

  '그래서',
  '따라서',

  'causes',
  'caused by',
  'because of',
  'due to',
  'results from',
  'leads to'

];


// ------------------------------------------------------------
// 14-2. Weak Relation Expressions
// ------------------------------------------------------------

const weakRelationPatterns = [

  '관련될 수',
  '관련이 있을 수',

  '나타낼 수',
  '나타날 수',

  '의미할 수',

  '가능성이',

  '일 수 있다',
  '일 수 있습니다',

  'may',
  'might',
  'could',

  'associated with',
  'related to'

];


// ------------------------------------------------------------
// 14-3. Stop Words
// ------------------------------------------------------------

const stopWords =
  new Set([

    '고양이',
    '고양이가',
    '고양이는',

    '우다다',
    '행동',
    '현상',

    '그리고',
    '하지만',
    '또한',

    '것',
    '수',
    '있다',
    '있습니다',
    '합니다',
    '됩니다',

    'the',
    'a',
    'an',
    'and',
    'or',
    'is',
    'are',
    'of',
    'to',
    'for',
    'with',
    'from',
    'by',

    'frap',
    'fraps'

  ]);


// ------------------------------------------------------------
// 14-4. Token Normalization
// ------------------------------------------------------------

function normalizeToken(token) {

  let value =
    normalizeText(token)
      .replace(
        /[^0-9a-z가-힣]/gi,
        ''
      );

  if (!value) {
    return '';
  }

  const endings = [

    '으로부터',
    '에게서',

    '으로',
    '에서',
    '에게',

    '이나',
    '거나',

    '은',
    '는',
    '이',
    '가',

    '을',
    '를',

    '에',
    '의',

    '와',
    '과',

    '로'

  ];

  for (
    const ending
    of endings
  ) {

    if (
      value.length >
      ending.length + 1 &&
      value.endsWith(ending)
    ) {

      value =
        value.slice(
          0,
          -ending.length
        );

      break;
    }
  }

  return value;
}


function contentTokens(text) {

  const rawTokens =
    normalizeText(text)
      .replace(
        /[^0-9a-z가-힣]+/gi,
        ' '
      )
      .split(/\s+/)
      .map(normalizeToken)
      .filter(Boolean);

  const filtered =
    rawTokens
      .filter(token =>

        token.length >= 2 &&
        !stopWords.has(token)

      );

  return [
    ...new Set(filtered)
  ];
}


// ------------------------------------------------------------
// 14-5. Fact Metadata
// ------------------------------------------------------------

function normalizeConfidence(fact) {

  return cleanText(
    fact?.confidence
  ).toUpperCase();
}


function normalizeScriptUse(fact) {

  return cleanText(
    fact?.script_use
  ).toUpperCase();
}


function containsStrongCausal(text) {

  return strongCausalPatterns
    .some(pattern =>

      containsPattern(
        text,
        pattern
      )

    );
}


function containsWeakRelation(text) {

  return weakRelationPatterns
    .some(pattern =>

      containsPattern(
        text,
        pattern
      )

    );
}


// ------------------------------------------------------------
// 14-6. Extract Causal Sentences
// ------------------------------------------------------------

const scriptSentences =
  splitSentences(
    `${hook} ${narration}`
  );

const causalSentences =
  scriptSentences
    .filter(sentence =>

      containsStrongCausal(
        sentence
      )

    );


// ------------------------------------------------------------
// 14-7. Candidate Supporting Facts
// ------------------------------------------------------------

const usedFacts =
  facts
    .filter(fact =>

      usedFactIds.includes(
        cleanText(fact.id)
      )

    );

const highAllowFacts =
  usedFacts
    .filter(fact =>

      normalizeConfidence(fact) ===
        'HIGH' &&

      normalizeScriptUse(fact) ===
        'ALLOW'

    );

const highAllowCausalFacts =
  highAllowFacts
    .filter(fact =>

      containsStrongCausal(
        getFactText(fact)
      )

    );


// ------------------------------------------------------------
// 14-8. Sentence ↔ Fact Support Matching
// ------------------------------------------------------------

const causalChecks = [];

for (
  const sentence
  of causalSentences
) {

  const sentenceTokens =
    contentTokens(
      sentence
    );

  let bestMatch = null;

  for (
    const fact
    of highAllowCausalFacts
  ) {

    const factText =
      getFactText(fact);

    const factTokens =
      contentTokens(
        factText
      );

    const overlaps =
      sentenceTokens
        .filter(token =>
          factTokens.includes(token)
        );

    const uniqueOverlap =
      [
        ...new Set(overlaps)
      ];

    const overlapCount =
      uniqueOverlap.length;

    const denominator =
      Math.max(
        1,
        Math.min(
          sentenceTokens.length,
          factTokens.length
        )
      );

    const overlapRatio =
      overlapCount /
      denominator;

    const match = {

      fact_id:
        cleanText(fact.id),

      confidence:
        normalizeConfidence(fact),

      script_use:
        normalizeScriptUse(fact),

      fact_text:
        factText,

      shared_tokens:
        uniqueOverlap,

      overlap_count:
        overlapCount,

      overlap_ratio:
        Number(
          overlapRatio.toFixed(3)
        )

    };

    if (
      !bestMatch ||
      match.overlap_count >
        bestMatch.overlap_count ||
      (
        match.overlap_count ===
          bestMatch.overlap_count &&
        match.overlap_ratio >
          bestMatch.overlap_ratio
      )
    ) {

      bestMatch =
        match;
    }
  }

  const supported =
    Boolean(
      bestMatch &&
      (
        bestMatch.overlap_count >= 2 ||
        (
          bestMatch.overlap_count >= 1 &&
          bestMatch.overlap_ratio >= 0.5
        )
      )
    );

  causalChecks.push({

    sentence,

    supported,

    best_match:
      bestMatch

  });

  if (!supported) {

    errors.push(
      `검증되지 않은 인과 문장 감지: ${sentence}`
    );
  }
}


// ------------------------------------------------------------
// 14-9. Strength Escalation Guard
// ------------------------------------------------------------

const weakQualifiedFacts =
  usedFacts
    .filter(fact => {

      const confidence =
        normalizeConfidence(fact);

      const scriptUse =
        normalizeScriptUse(fact);

      const text =
        getFactText(fact);

      return (

        (
          confidence === 'MEDIUM' ||
          scriptUse === 'QUALIFY'
        ) &&

        containsWeakRelation(text)

      );
    });

if (
  causalSentences.length > 0 &&
  weakQualifiedFacts.length > 0
) {

  for (
    const fact
    of weakQualifiedFacts
  ) {

    const factTokens =
      contentTokens(
        getFactText(fact)
      );

    for (
      const sentence
      of causalSentences
    ) {

      const sentenceTokens =
        contentTokens(
          sentence
        );

      const overlapCount =
        sentenceTokens
          .filter(token =>
            factTokens.includes(token)
          )
          .length;

      if (
        overlapCount >= 2
      ) {

        errors.push(
          `QUALIFY Fact ${cleanText(fact.id)}의 가능성/관련성이 직접 인과관계로 강화되었습니다.`
        );
      }
    }
  }
}


// ============================================================
// 15. Duration Preflight
// ============================================================

const charsPerSecond =
  4.1;

const speechText =
  cleanText(
    `${hook} ${narration}`
  )
    .replace(
      /[\s.,!?'"“”‘’()[\]{}:;·…/\\|_-]/g,
      ''
    );

const characterCount =
  cleanText(
    `${hook} ${narration} ${closing}`
  ).length;

const wordCount =
  cleanText(
    `${hook} ${narration}`
  )
    .split(/\s+/)
    .filter(Boolean)
    .length;

const speechCharacterCount =
  speechText.length;

const estimatedDurationSec =
  Number(
    (
      speechCharacterCount /
      charsPerSecond
    ).toFixed(1)
  );

const durationRatio =
  Number(
    (
      estimatedDurationSec /
      requestedDurationSec
    ).toFixed(3)
  );

let durationPreflight =
  'PASS';

if (
  durationRatio < 0.5
) {

  durationPreflight =
    'FAIL';

  errors.push(
    `대본 길이 심각 부족: 예상 ${estimatedDurationSec}초 / 목표 ${requestedDurationSec}초`
  );

} else if (
  durationRatio < 0.7
) {

  durationPreflight =
    'WARN';

  warnings.push(
    `대본 길이 부족 가능성: 예상 ${estimatedDurationSec}초 / 목표 ${requestedDurationSec}초`
  );
}


// ============================================================
// 16. Error Type Classification
// ============================================================

const causalIntegrityFailed =
  errors.some(error =>

    error.includes(
      '검증되지 않은 인과'
    ) ||

    error.includes(
      '직접 인과관계로 강화'
    )

  );

const roleBoundaryFailed =
  errors.some(error =>

    error.includes(
      '역할 침범'
    )

  );

const factReferenceFailed =
  errors.some(error =>

    error.includes(
      'Fact ID'
    )

  );

const qualifyTrackingFailed =
  errors.some(error =>

    error.includes(
      'qualified_fact_ids'
    ) ||

    error.includes(
      'QUALIFY Fact'
    )

  );

const structureFailed =
  errors.some(error =>

    error.includes(
      'script_version'
    ) ||

    error.includes(
      'hook이'
    ) ||

    error.includes(
      'narration이'
    )

  );


// ============================================================
// 17. Final Routing
// ============================================================
//
// IMPORTANT:
//
// This is Script Validator Expanded.
// Evidence Expansion has ALREADY happened once.
//
// Therefore:
//
// duration FAIL
//   → DO NOT request Evidence Expansion again
//   → STOP
//
// ============================================================

let status =
  'PASS';

let needsEvidenceExpansion =
  false;

let readyForSceneAdapter =
  true;

let nextRoute =
  'scene_adapter';


if (
  causalIntegrityFailed ||
  roleBoundaryFailed ||
  factReferenceFailed ||
  qualifyTrackingFailed ||
  structureFailed ||
  closing
) {

  status =
    'FAIL';

  needsEvidenceExpansion =
    false;

  readyForSceneAdapter =
    false;

  nextRoute =
    'script_review';

} else if (
  durationPreflight === 'FAIL'
) {

  status =
    'FAIL';

  needsEvidenceExpansion =
    false;

  readyForSceneAdapter =
    false;

  nextRoute =
    'stop';

} else if (
  errors.length > 0
) {

  status =
    'FAIL';

  needsEvidenceExpansion =
    false;

  readyForSceneAdapter =
    false;

  nextRoute =
    'script_review';

} else if (
  warnings.length > 0
) {

  status =
    'WARN';

  needsEvidenceExpansion =
    false;

  readyForSceneAdapter =
    true;

  nextRoute =
    'scene_adapter';
}


// ============================================================
// 18. Validation Summary
// ============================================================

const validation = {

  structure:
    structureFailed
      ? 'FAIL'
      : 'PASS',

  fact_id_reference:
    factReferenceFailed
      ? 'FAIL'
      : 'PASS',

  qualify_tracking:
    qualifyTrackingFailed
      ? 'FAIL'
      : 'PASS',

  closing:
    closing
      ? 'FAIL'
      : 'PASS',

  role_boundary:
    roleBoundaryFailed
      ? 'FAIL'
      : 'PASS',

  advice_detection:
    foundAdvice.length > 0
      ? 'WARN'
      : 'PASS',

  causal_integrity:
    causalIntegrityFailed
      ? 'FAIL'
      : 'PASS',

  duration_preflight:
    durationPreflight,

  warnings,

  errors

};


// ============================================================
// 19. Output
// ============================================================

return [
  {
    json: {

      stage:
        'script_validated',

      validator_version:
        '1.6',

      script_version:
        scriptVersion,

      title,

      hook,

      narration,

      closing,

      used_fact_ids:
        usedFactIds,

      qualified_fact_ids:
        qualifiedFactIds,

      validation,

      causal_debug: {

        causal_sentence_count:
          causalSentences.length,

        causal_sentences:
          causalSentences,

        eligible_high_allow_causal_fact_ids:
          highAllowCausalFacts
            .map(fact =>
              cleanText(fact.id)
            ),

